/* data/maulid/barzanji.js - Maulid Barzanji (Arab, transliterasi, terjemah). Dibuat oleh template-kitab/maulid_dari_md.py.
   Satu bait = {no, ar, lt, id}. Boleh diedit langsung. */
registerMaulid({"id": "barzanji", "judul": "Maulid Barzanji", "sumber": "'Iqdul Jauhar fi Maulidin Nabiyyil Azhar, karya Sayyid Ja'far bin Hasan Al-Barzanji. Teks Arab disalin ulang dari PDF Majmu'atul Mawalid; transliterasi & terjemah disusun ulang - mohon ditashih.",bagian:[
{judul:"Pembuka: Abtadi'ul Imla'a",isi:[
{"ar": "اَلْجَنَّةُ وَنَعِيْمُهَا سَعْدٌ لِمَنْ يُصَلِّيْ وَيُسَلِّمُ وَيُبَارِكُ عَلَيْهِ", "lt": "Al-jannatu wa na‘îmuhâ sa‘dun liman yushallî wa yusallimu wa yubâriku ‘alaih", "id": "Surga dan kenikmatannya adalah kebahagiaan bagi orang yang bershalawat, mengucapkan salam, dan memohonkan keberkahan untuk beliau.", "no": 1},
{"ar": "بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيْمِ", "lt": "Bismillâhir-raḥmânir-raḥîm", "id": "Dengan nama Allah Yang Maha Pengasih lagi Maha Penyayang.", "no": 2},
{"ar": "أَبْتَدِئُ الْإِمْلَاءَ بِاسْمِ الذَّاتِ الْعَلِيَّةْ، مُسْتَدِرًّا فَيْضَ الْبَرَكَاتِ عَلَى مَا أَنَالَهُ وَأَوْلَاهْ", "lt": "Abtadi'ul-imlâ'a bismidz-dzâtil-‘aliyyah, mustadirran faidlal-barakâti ‘alâ mâ anâlahû wa aulâh", "id": "Aku memulai penulisan (kitab ini) dengan menyebut nama Dzat Yang Mahatinggi, seraya memohon limpahan keberkahan atas apa yang telah Dia anugerahkan dan berikan.", "no": 3},
{"ar": "وَأُثَنِّيْ بِحَمْدٍ مَوَارِدُهُ سَائِغَةٌ هَنِيَّةْ، مُمْتَطِيًا مِنَ الشُّكْرِ الْجَمِيْلِ مَطَايَاهْ", "lt": "Wa utsannî biḥamdin mawâriduhû sâ'ighatun haniyyah, mumtaṭiyan minasy-syukril-jamîli maṭâyâh", "id": "Kemudian aku lanjutkan dengan pujian yang sumber-sumbernya segar dan menyenangkan, seraya menunggangi kendaraan rasa syukur yang indah.", "no": 4},
{"ar": "وَأُصَلِّيْ وَأُسَلِّمُ عَلَى النُّوْرِ الْمَوْصُوْفِ بِالتَّقَدُّمِ وَالْأَوَّلِيَّةْ، الْمُنْتَقِلِ فِي الْغُرَرِ الْكَرِيْمَةِ وَالْجِبَاهْ", "lt": "Wa ushallî wa usallimu ‘alan-nûril-maushûfi bit-taqaddumi wal-awwaliyyah, al-muntaqili fil-ghuraril-karîmati wal-jibâh", "id": "Aku bershalawat dan bersalam kepada cahaya (Nabi) yang disifati dengan keterdahuluan dan keawalan, yang berpindah-pindah pada wajah-wajah dan dahi-dahi yang mulia.", "no": 5},
{"ar": "وَأَسْتَمْنِحُ اللهَ تَعَالَى رِضْوَانًا يَخُصُّ الْعِتْرَةَ الطَّاهِرَةَ النَّبَوِيَّةْ، وَيَعُمُّ الصَّحَابَةَ وَالْأَتْبَاعَ وَمَنْ وَالَاهْ", "lt": "Wa astamniḥullâha ta‘âlâ ridlwânan yakhushshul-‘itrataṭ-ṭâhiratan-nabawiyyah, wa ya‘ummush-shaḥâbata wal-atbâ‘a wa man wâlâh", "id": "Aku memohon kepada Allah Ta‘ala keridaan yang khusus bagi keturunan Nabi yang suci, dan meliputi para sahabat, para pengikut, dan siapa saja yang setia kepada beliau.", "no": 6},
{"ar": "وَأَسْتَجْدِيْهِ هِدَايَةً لِسُلُوْكِ السُّبُلِ الْوَاضِحَةِ الْجَلِيَّةْ، وَحِفْظًا مِنَ الْغَوَايَةِ فِيْ خِطَطِ الْخَطَأِ وَخُطَاهْ", "lt": "Wa astajdîhi hidâyatan lisulûkis-subulil-wâdliḥatil-jaliyyah, wa ḥifdhan minal-ghawâyati fî khiṭaṭil-khaṭa'i wa khuṭâh", "id": "Aku memohon kepada-Nya petunjuk untuk menempuh jalan-jalan yang terang dan jelas, serta penjagaan dari kesesatan di jalan dan langkah-langkah yang keliru.", "no": 7},
{"ar": "وَأَنْشُرُ مِنْ قِصَّةِ الْمَوْلِدِ النَّبَوِيِّ بُرُوْدًا حِسَانًا عَبْقَرِيَّةْ، نَاظِمًا مِنَ النَّسَبِ الشَّرِيْفِ عِقْدًا تُحَلَّى الْمَسَامِعُ بِحُلَاهْ", "lt": "Wa ansyuru min qishshatil-maulidin-nabawiyyi burûdan ḥisânan ‘abqariyyah, nâdhiman minan-nasabisy-syarîfi ‘iqdan tuḥallal-masâmi‘u biḥulâh", "id": "Aku bentangkan dari kisah kelahiran Nabi kain-kain yang indah dan menakjubkan, seraya merangkai dari nasabnya yang mulia sebuah kalung yang perhiasannya menghiasi pendengaran.", "no": 8},
{"ar": "وَأَسْتَعِيْنُ بِحَوْلِ اللهِ تَعَالَى وَقُوَّتِهِ الْقَوِيَّةْ، فَإِنَّهُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهْ", "lt": "Wa asta‘înu biḥaulillâhi ta‘âlâ wa quwwatihil-qawiyyah, fa innahû lâ ḥaula wa lâ quwwata illâ billâh", "id": "Aku memohon pertolongan dengan daya dan kekuatan Allah Ta‘ala yang Mahakuat, karena sesungguhnya tiada daya dan kekuatan kecuali dengan (pertolongan) Allah.", "no": 9},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 10}]},
{judul:"Nasab Nabi: Wa Ba'du Fa Aqulu",isi:[
{"ar": "وَبَعْدُ فَأَقُوْلُ: هُوَ سَيِّدُنَا مُحَمَّدُ بْنُ عَبْدِ اللهِ بْنِ عَبْدِ الْمُطَّلِبِ، وَاسْمُهُ شَيْبَةُ الْحَمْدِ حُمِدَتْ خِصَالُهُ السَّنِيَّةْ", "lt": "Wa ba‘du fa aqûlu: huwa sayyidunâ muḥammadubnu ‘abdillâhibni ‘abdil-muṭṭalib, wasmuhû syaibatul-ḥamdi ḥumidat khishâluhus-saniyyah", "id": "Selanjutnya aku katakan: Beliau adalah junjungan kita Muhammad putra Abdullah putra Abdul Muthalib, yang bernama asli Syaibatul Hamd, yang terpuji sifat-sifatnya yang luhur.", "no": 1},
{"ar": "ابْنِ هَاشِمٍ وَاسْمُهُ عَمْرُو بْنُ عَبْدِ مَنَافٍ وَاسْمُهُ الْمُغِيْرَةُ الَّذِيْ يُنْتَمَى الْاِرْتِقَاءُ لِعُلْيَاهْ", "lt": "Ibni hâsyimin wasmuhû ‘amrubnu ‘abdi manâfin wasmuhul-mughîratul-ladzî yuntamal-irtiqâ'u li‘ulyâh", "id": "Putra Hasyim yang bernama asli Amr, putra Abdu Manaf yang bernama asli Al-Mughirah, yang kepada ketinggiannya dinisbatkan segala kemajuan.", "no": 2},
{"ar": "ابْنِ قُصَيٍّ وَاسْمُهُ مُجَمِّعٌ سُمِّيَ بِقُصَيٍّ لِتَقَاصِيْهِ فِيْ بِلَادِ قُضَاعَةَ الْقَصِيَّةْ، إِلَى أَنْ أَعَادَهُ اللهُ تَعَالَى إِلَى الْحَرَمِ الْمُحْتَرَمِ فَحَمَى حِمَاهْ", "lt": "Ibni qushayyin wasmuhû mujammi‘un summiya biqushayyin litaqâshîhi fî bilâdi qudlâ‘atal-qashiyyah, ilâ an a‘âdahullâhu ta‘âlâ ilal-ḥaramil-muḥtarami faḥamâ ḥimâh", "id": "Putra Qushay yang bernama asli Mujammi‘; ia dinamai Qushay karena lama terasing di negeri Qudha‘ah yang jauh, hingga Allah Ta‘ala mengembalikannya ke tanah haram yang dihormati, lalu ia menjaga wilayahnya.", "no": 3},
{"ar": "ابْنِ كِلَابٍ وَاسْمُهُ حَكِيْمُ بْنُ مُرَّةَ بْنِ كَعْبِ بْنِ لُؤَيِّ بْنِ غَالِبِ بْنِ فِهْرٍ، وَاسْمُهُ قُرَيْشٌ وَإِلَيْهِ تُنْسَبُ الْبُطُوْنُ الْقُرَشِيَّةْ", "lt": "Ibni kilâbin wasmuhû ḥakîmubnu murrata bni ka‘bibni lu'ayyibni ghâlibibni fihr, wasmuhû quraisyun wa ilaihi tunsabul-buṭûnul-qurasyiyyah", "id": "Putra Kilab yang bernama asli Hakim, putra Murrah putra Ka‘ab putra Lu'ay putra Ghalib putra Fihr yang bernama Quraisy; kepadanyalah suku-suku Quraisy dinisbatkan.", "no": 4},
{"ar": "وَمَا فَوْقَهُ كِنَانِيٌّ كَمَا جَنَحَ إِلَيْهِ الْكَثِيْرُ وَارْتَضَاهْ", "lt": "Wa mâ fauqahû kinâniyyun kamâ janaḥa ilaihil-katsîru wartadlâh", "id": "Sedangkan leluhur di atasnya adalah keturunan Kinanah, sebagaimana pendapat yang dipegang dan disetujui oleh kebanyakan ulama.", "no": 5},
{"ar": "ابْنِ مَالِكِ بْنِ النَّضْرِ بْنِ كِنَانَةَ بْنِ خُزَيْمَةَ بْنِ مُدْرِكَةَ بْنِ إِلْيَاسَ، وَهُوَ أَوَّلُ مَنْ أَهْدَى الْبُدْنَ إِلَى الرِّحَابِ الْحَرَمِيَّةْ، وَسُمِعَ فِيْ صُلْبِهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَكَرَ اللهَ تَعَالَى وَلَبَّاهْ", "lt": "Ibni mâlikibnin-nadlribni kinânata bni khuzaimata bni mudrikata bni ilyâs, wa huwa awwalu man ahdal-budna ilar-riḥâbil-ḥaramiyyah, wa sumi‘a fî shulbihin-nabiyyu shallallâhu ‘alaihi wa sallama dzakarallâha ta‘âlâ wa labbâh", "id": "Putra Malik putra An-Nadhr putra Kinanah putra Khuzaimah putra Mudrikah putra Ilyas. Ilyas adalah orang pertama yang menghadiahkan unta kurban ke tanah haram, dan dari sulbinya terdengar Nabi ﷺ berzikir kepada Allah Ta‘ala dan bertalbiah.", "no": 6},
{"ar": "ابْنِ مُضَرَ بْنِ نِزَارِ بْنِ مَعَدِّ بْنِ عَدْنَانَ، وَهٰذَا سِلْكٌ نَظَّمَتْ فَرَائِدَهُ بَنَانُ السُّنَّةِ السَّنِيَّةْ", "lt": "Ibni mudlarabni nizâribni ma‘addibni ‘adnân, wa hâdzâ silkun nadhdhamat farâ'idahû banânus-sunnatis-saniyyah", "id": "Putra Mudhar putra Nizar putra Ma‘ad putra Adnan. Inilah untaian (nasab) yang mutiara-mutiaranya dirangkai oleh jari-jemari sunnah yang luhur.", "no": 7},
{"ar": "وَرَفْعُهُ إِلَى الْخَلِيْلِ إِبْرَاهِيْمَ أَمْسَكَ عَنْهُ الشَّارِعُ وَأَبَاهْ", "lt": "Wa raf‘uhû ilal-khalîli ibrâhîma amsaka ‘anhusy-syâri‘u wa abâh", "id": "Adapun menyambungkan (nasab) ini sampai kepada Al-Khalil Ibrahim, Nabi ﷺ menahan diri darinya dan enggan merincinya.", "no": 8},
{"ar": "وَعَدْنَانُ بِلَا رَيْبٍ عِنْدَ ذَوِي الْعُلُوْمِ النَّسَبِيَّةْ، إِلَى الذَّبِيْحِ إِسْمَاعِيْلَ نِسْبَتُهُ وَمُنْتَمَاهْ", "lt": "Wa ‘adnânu bilâ raibin ‘inda dzawil-‘ulûmin-nasabiyyah, iladz-dzabîḥi ismâ‘îla nisbatuhû wa muntamâh", "id": "Adapun Adnan, tanpa keraguan menurut para ahli ilmu nasab, bersambung nasab dan silsilahnya kepada Isma‘il yang disembelih (Adz-Dzabih).", "no": 9},
{"ar": "فَأَعْظِمْ بِهِ مِنْ عِقْدٍ تَأَلَّقَتْ كَوَاكِبُهُ الدُّرِّيَّةْ، وَكَيْفَ لَا وَالسَّيِّدُ الْأَكْرَمُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاسِطَتُهُ الْمُنْتَقَاهْ", "lt": "Fa a‘dhim bihî min ‘iqdin ta'allaqat kawâkibuhud-durriyyah, wa kaifa lâ was-sayyidul-akramu shallallâhu ‘alaihi wa sallama wâsiṭatuhul-muntaqâh", "id": "Betapa agung untaian (nasab) ini, bintang-bintangnya berkilau bagai mutiara. Bagaimana tidak, sedangkan junjungan yang paling mulia ﷺ adalah permata pilihan di tengah-tengahnya.", "no": 10},
{"ar": "نَسَبٌ تَحْسِبُ الْعُلَا بِحُلَاهُ ۞ قَلَّدَتْهَا نُجُوْمَهَا الْجَوْزَاءُ", "lt": "Nasabun taḥsibul-‘ulâ biḥulâhu ۞ qalladat-hâ nujûmahal-jauzâ'u", "id": "Nasab yang dengan perhiasannya engkau kira ketinggian itu sendiri telah dikalungi oleh bintang-bintang Jauza'.", "no": 11},
{"ar": "حَبَّذَا عِقْدُ سُؤْدَدٍ وَفَخَارٍ ۞ أَنْتَ فِيْهِ الْيَتِيْمَةُ الْعَصْمَاءُ", "lt": "Ḥabbadzâ ‘iqdu su'dadin wa fakhârin ۞ anta fîhil-yatîmatul-‘ashmâ'u", "id": "Alangkah indahnya untaian kemuliaan dan kebanggaan itu, dan engkaulah mutiara tunggal yang terjaga di dalamnya.", "no": 12},
{"ar": "وَأَكْرِمْ بِهِ مِنْ نَسَبٍ طَهَّرَهُ اللهُ تَعَالَى مِنْ سِفَاحِ الْجَاهِلِيَّةْ، أَوْرَدَ الزَّيْنُ الْعِرَاقِيُّ وَارِدَهُ فِيْ مَوْرِدِهِ الْهَنِيِّ وَرَوَاهْ", "lt": "Wa akrim bihî min nasabin ṭahharahullâhu ta‘âlâ min sifâḥil-jâhiliyyah, auradaz-zainul-‘irâqiyyu wâridahû fî maurídihil-haniyyi wa rawâh", "id": "Betapa mulia nasab yang telah Allah Ta‘ala sucikan dari perzinaan zaman jahiliah. Al-Hafizh Zainuddin Al-‘Iraqi telah menyebutkan (riwayat) tentangnya dalam karyanya yang indah dan meriwayatkannya.", "no": 13},
{"ar": "حَفِظَ الْإِلٰهُ كَرَامَةً لِمُحَمَّدٍ ۞ آبَاءَهُ الْأَمْجَادَ صَوْنًا لِاسْمِهِ", "lt": "Ḥafidhal-ilâhu karâmatan limuḥammadin ۞ âbâ'ahul-amjâda shaunan lismihî", "id": "Allah menjaga para leluhur Muhammad yang mulia sebagai penghormatan kepadanya dan untuk memelihara namanya.", "no": 14},
{"ar": "تَرَكُوا السِّفَاحَ فَلَمْ يُصِبْهُمْ عَارُهُ ۞ مِنْ آدَمٍ وَإِلَى أَبِيْهِ وَأُمِّهِ", "lt": "Tarakus-sifâḥa falam yushibhum ‘âruhû ۞ min âdamin wa ilâ abîhi wa ummihî", "id": "Mereka meninggalkan perzinaan sehingga tak tertimpa aibnya, sejak Adam hingga ayah dan ibunya.", "no": 15},
{"ar": "سَرَاةٌ سَرَى نُوْرُ النُّبُوَّةِ فِيْ أَسَارِيْرِ غُرَرِهِمُ الْبَهِيَّةْ، وَبَدَرَ بَدْرُهُ فِيْ جَبِيْنِ جَدِّهِ عَبْدِ الْمُطَّلِبِ وَابْنِهِ عَبْدِ اللهْ", "lt": "Sarâtun sarâ nûrun-nubuwwati fî asârîri ghurarihimul-bahiyyah, wa badara badruhû fî jabîni jaddihî ‘abdil-muṭṭalibi wabnihî ‘abdillâh", "id": "Mereka adalah para pemimpin yang cahaya kenabian mengalir pada garis-garis wajah mereka yang berseri, dan purnamanya terbit di dahi kakeknya, Abdul Muthalib, dan putranya, Abdullah.", "no": 16},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 17}]},
{judul:"Kehamilan Sayyidah Aminah",isi:[
{"ar": "وَلَمَّا أَرَادَ اللهُ تَعَالَى إِبْرَازَ حَقِيْقَتِهِ الْمُحَمَّدِيَّةْ، وَإِظْهَارَهُ جِسْمًا وَرُوْحًا بِصُوْرَتِهِ وَمَعْنَاهْ", "lt": "Wa lammâ arâdallâhu ta‘âlâ ibrâza ḥaqîqatihil-muḥammadiyyah, wa idh-hârahû jisman wa rûḥan bishûratihî wa ma‘nâh", "id": "Ketika Allah Ta‘ala hendak menampakkan hakikat Muhammad dan memunculkannya dalam jasad dan ruh, dalam rupa dan maknanya,", "no": 1},
{"ar": "نَقَلَهُ إِلَى مَقَرِّهِ مِنْ صَدَفَةِ آمِنَةَ الزُّهْرِيَّةْ، وَخَصَّهَا الْقَرِيْبُ الْمُجِيْبُ بِأَنْ تَكُوْنَ أُمًّا لِمُصْطَفَاهْ", "lt": "Naqalahû ilâ maqarrihî min shadafati âminataz-zuhriyyah, wa khash-shahal-qarîbul-mujîbu bi'an takûna umman limushṭafâh", "id": "Dia memindahkannya ke tempatnya di dalam kerang (rahim) Aminah dari Bani Zuhrah, dan (Allah) Yang Mahadekat lagi Maha Mengabulkan mengistimewakannya untuk menjadi ibu bagi (Nabi) pilihan-Nya.", "no": 2},
{"ar": "وَنُوْدِيَ فِي السَّمٰوَاتِ وَالْأَرْضِ بِحَمْلِهَا لِأَنْوَارِهِ الذَّاتِيَّةْ، وَصَبَا كُلُّ صَبٍّ لِهُبُوْبِ نَسِيْمِ صَبَاهْ", "lt": "Wa nûdiya fis-samâwâti wal-ardli biḥamlihâ li'anwârihidz-dzâtiyyah, wa shabâ kullu shabbin lihubûbi nasîmi shabâh", "id": "Diserukan di langit dan bumi tentang kehamilannya yang membawa cahaya-cahaya beliau, dan setiap perindu menjadi rindu karena embusan angin sepoi-sepoi kerinduannya.", "no": 3},
{"ar": "وَكُسِيَتِ الْأَرْضُ بَعْدَ طُوْلِ جَدْبِهَا مِنَ النَّبَاتِ حُلَلًا سُنْدُسِيَّةْ، وَأَيْنَعَتِ الثِّمَارُ وَأَدْنَى الشَّجَرُ لِلْجَانِيْ جَنَاهْ", "lt": "Wa kusiyatil-ardlu ba‘da ṭûli jadbihâ minan-nabâti ḥulalan sundusiyyah, wa aina‘atits-tsimâru wa adnasy-syajaru lil-jânî janâh", "id": "Bumi yang lama kering kerontang diselimuti tumbuhan bagai pakaian sutra, buah-buahan pun ranum, dan pepohonan mendekatkan buahnya kepada pemetiknya.", "no": 4},
{"ar": "وَنَطَقَتْ بِحَمْلِهِ كُلُّ دَابَّةٍ بِفِصَاحِ الْأَلْسُنِ الْعَرَبِيَّةْ، وَخَرَّتِ الْأَسِرَّةُ وَالْأَصْنَامُ عَلَى الْوُجُوْهِ وَالْأَفْوَاهْ", "lt": "Wa naṭaqat biḥamlihî kullu dâbbatin bifishâḥil-alsunil-‘arabiyyah, wa kharratil-asirratu wal-ashnâmu ‘alal-wujûhi wal-afwâh", "id": "Setiap binatang berbicara tentang kehamilannya dengan bahasa Arab yang fasih, dan singgasana-singgasana serta berhala-berhala tersungkur di atas muka dan mulutnya.", "no": 5},
{"ar": "وَتَبَاشَرَتْ وُحُوْشُ الْمَشَارِقِ وَالْمَغَارِبِ وَدَوَابُّهَا الْبَحْرِيَّةْ، وَاحْتَسَتِ الْعَوَالِمُ مِنَ السُّرُوْرِ كَأْسَ حُمَيَّاهْ", "lt": "Wa tabâsyarat wuḥûsyul-masyâriqi wal-maghâribi wa dawâbbuhal-baḥriyyah, waḥtasatil-‘awâlimu minas-surûri ka'sa ḥumayyâh", "id": "Binatang-binatang liar di timur dan barat serta binatang-binatang laut saling memberi kabar gembira, dan seluruh alam meneguk gelas kegembiraan yang memabukkan.", "no": 6},
{"ar": "وَبُشِّرَتِ الْجِنُّ بِإِظْلَالِ زَمَنِهِ، وَانْتُهِكَتِ الْكَهَانَةُ وَرَهِبَتِ الرَّهْبَانِيَّةْ، وَلَهِجَ بِخَبَرِهِ كُلُّ حَبْرٍ خَبِيْرٍ وَفِيْ حُلَا حُسْنِهِ تَاهْ", "lt": "Wa busysyiratil-jinnu bi'idhlâli zamanih, wantuhikatil-kahânatu wa rahibatir-ruhbâniyyah, wa lahija bikhabarihî kullu ḥabrin khabîrin wa fî ḥulâ ḥusnihî tâh", "id": "Bangsa jin diberi kabar gembira tentang dekatnya masa kedatangannya, perdukunan dihancurkan, para rahib menjadi takut, dan setiap pendeta yang alim ramai membicarakan kabarnya dan terpesona oleh keindahannya.", "no": 7},
{"ar": "وَأُتِيَتْ أُمُّهُ فِي الْمَنَامِ فَقِيْلَ لَهَا: إِنَّكِ قَدْ حَمَلْتِ بِسَيِّدِ الْعَالَمِيْنَ وَخَيْرِ الْبَرِيَّةْ، فَسَمِّيْهِ إِذَا وَضَعْتِهِ مُحَمَّدًا لِأَنَّهُ سَتُحْمَدُ عُقْبَاهْ", "lt": "Wa utiyat ummuhû fil-manâmi faqîla lahâ: innaki qad ḥamalti bisayyidil-‘âlamîna wa khairil-bariyyah, fasammîhi idzâ wadla‘tihî muḥammadan li'annahû satuḥmadu ‘uqbâh", "id": "Ibunya didatangi dalam mimpi, lalu dikatakan kepadanya: Sesungguhnya engkau sedang mengandung pemimpin semesta alam dan sebaik-baik makhluk; maka bila engkau melahirkannya, namailah ia Muhammad, karena kelak akhir urusannya akan terpuji.", "no": 8},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 9}]},
{judul:"Wafat Ayahanda dan Kelahiran Nabi",isi:[
{"ar": "وَلَمَّا تَمَّ مِنْ حَمْلِهِ شَهْرَانِ عَلَى مَشْهُوْرِ الْأَقْوَالِ الْمَرْوِيَّةْ، تُوُفِّيَ بِالْمَدِيْنَةِ الْمُنَوَّرَةِ أَبُوْهُ عَبْدُ اللهْ", "lt": "Wa lammâ tamma min ḥamlihî syahrâni ‘alâ masyhûril-aqwâlil-marwiyyah, tuwuffiya bil-madînatil-munawwarati abûhu ‘abdullâh", "id": "Ketika kandungannya genap dua bulan, menurut pendapat yang masyhur di antara riwayat-riwayat, ayahnya, Abdullah, wafat di Madinah Al-Munawwarah.", "no": 1},
{"ar": "وَكَانَ قَدِ اجْتَازَ بِأَخْوَالِهِ بَنِيْ عَدِيٍّ مِنَ الطَّائِفَةِ النَّجَّارِيَّةْ، وَمَكَثَ فِيْهِمْ شَهْرًا سَقِيْمًا يُعَانُوْنَ سُقْمَهُ وَشَكْوَاهْ", "lt": "Wa kâna qadij-tâza bi'akhwâlihî banî ‘adiyyin minaṭ-ṭâ'ifatin-najjâriyyah, wa makatsa fîhim syahran saqîman yu‘ânûna suqmahû wa syakwâh", "id": "Ia singgah di tempat paman-paman (dari pihak ibu) Bani ‘Adi dari kabilah Bani Najjar, lalu tinggal di tengah mereka selama sebulan dalam keadaan sakit, sementara mereka merawat sakit dan keluhannya.", "no": 2},
{"ar": "وَلَمَّا تَمَّ مِنْ حَمْلِهِ عَلَى الرَّاجِحِ تِسْعَةُ أَشْهُرٍ قَمَرِيَّةْ، وَآنَ لِلزَّمَانِ أَنْ يَنْجَلِيَ عَنْهُ صَدَاهْ", "lt": "Wa lammâ tamma min ḥamlihî ‘alar-râjiḥi tis‘atu asyhurin qamariyyah, wa âna liz-zamâni an yanjaliya ‘anhu shadâh", "id": "Ketika kandungannya, menurut pendapat yang kuat, genap sembilan bulan qamariyah, dan telah tiba saatnya zaman disingkapkan dari karatnya,", "no": 3},
{"ar": "حَضَرَ أُمَّهُ لَيْلَةَ مَوْلِدِهِ الشَّرِيْفِ آسِيَةُ وَمَرْيَمُ فِيْ نِسْوَةٍ مِنَ الْحَظِيْرَةِ الْقُدْسِيَّةْ، وَأَخَذَهَا الْمَخَاضُ فَوَلَدَتْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نُوْرًا يَتَلَأْلَأُ سَنَاهْ", "lt": "Ḥadlara ummahû lailata maulidihisy-syarîfi âsiyatu wa maryamu fî niswatin minal-ḥadhîratil-qudsiyyah, wa akhadzahal-makhâdlu fawaladat-hu shallallâhu ‘alaihi wa sallama nûran yatala'la'u sanâh", "id": "Pada malam kelahirannya yang mulia, ibunya didatangi oleh Asiyah dan Maryam bersama para wanita dari alam suci. Rasa sakit melahirkan pun datang, lalu ia melahirkan beliau ﷺ sebagai cahaya yang gemerlap sinarnya.", "no": 4}]},
{judul:"Mahallul Qiyam",isi:[
{"ar": "مَرْحَبًا يَا نُوْرَ عَيْنِيْ مَرْحَبًا ۞ مَرْحَبًا جَدَّ الْحُسَيْنِ مَرْحَبًا", "lt": "Marḥaban yâ nûra ‘ainî marḥabâ ۞ marḥaban jaddal-ḥusaini marḥabâ", "id": "Selamat datang, wahai cahaya mataku, selamat datang; selamat datang, wahai kakek Husain, selamat datang.", "no": 1},
{"ar": "وَمُحَيًّا كَالشَّمْسِ مِنْكَ مُضِيْءٌ ۞ أَسْفَرَتْ عَنْهُ لَيْلَةٌ غَرَّاءُ", "lt": "Wa muḥayyan kasy-syamsi minka mudlî'un ۞ asfarat ‘anhu lailatun gharrâ'u", "id": "Wajahmu bersinar terang bagai matahari, yang ditampakkan oleh malam yang cemerlang.", "no": 2},
{"ar": "لَيْلَةُ الْمَوْلِدِ الَّذِيْ كَانَ لِلدِّيْنِ ۞ سُرُوْرٌ بِيَوْمِهِ وَازْدِهَاءُ", "lt": "Lailatul-maulidil-ladzî kâna lid-dîni ۞ surûrun biyaumihî wazdihâ'u", "id": "Itulah malam kelahiran (Nabi), yang pada harinya agama mendapat kegembiraan dan kemegahan.", "no": 3},
{"ar": "يَوْمَ نَالَتْ بِوَضْعِهِ ابْنَةُ وَهْبٍ ۞ مِنْ فَخَارٍ مَا لَمْ تَنَلْهُ النِّسَاءُ", "lt": "Yauma nâlat biwadl‘ihibnatu wahbin ۞ min fakhârin mâ lam tanalhun-nisâ'u", "id": "Hari ketika putri Wahab (Aminah), dengan melahirkannya, meraih kebanggaan yang tidak pernah diraih wanita mana pun.", "no": 4},
{"ar": "وَأَتَتْ قَوْمَهَا بِأَفْضَلَ مِمَّا ۞ حَمَلَتْ قَبْلُ مَرْيَمُ الْعَذْرَاءُ", "lt": "Wa atat qaumahâ bi'afdlala mimmâ ۞ ḥamalat qablu maryamul-‘adzrâ'u", "id": "Ia datang kepada kaumnya membawa (bayi) yang lebih utama daripada yang dahulu dikandung Maryam yang perawan.", "no": 5},
{"ar": "مَوْلِدٌ كَانَ مِنْهُ فِيْ طَالِعِ الْكُفْرِ ۞ وَبَالٌ عَلَيْهِمْ وَوَبَاءُ", "lt": "Maulidun kâna minhu fî ṭâli‘il-kufri ۞ wabâlun ‘alaihim wa wabâ'u", "id": "Kelahiran yang membawa nasib buruk bagi kekafiran, menjadi bencana dan wabah bagi mereka.", "no": 6},
{"ar": "وَتَوَالَتْ بُشْرَى الْهَوَاتِفِ أَنْ قَدْ ۞ وُلِدَ الْمُصْطَفَى وَحَقَّ الْهَنَاءُ", "lt": "Wa tawâlat busyral-hawâtifi an qad ۞ wulidal-mushṭafâ wa ḥaqqal-hanâ'u", "id": "Kabar gembira dari suara-suara gaib datang silih berganti: telah lahir (Nabi) pilihan, dan pantaslah bersuka cita.", "no": 7},
{"ar": "هٰذَا وَقَدِ اسْتَحْسَنَ الْقِيَامَ عِنْدَ ذِكْرِ مَوْلِدِهِ الشَّرِيْفِ أَئِمَّةٌ ذَوُوْ رِوَايَةٍ وَرَوِيَّةْ، فَطُوْبَى لِمَنْ كَانَ تَعْظِيْمُهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ غَايَةَ مَرَامِهِ وَمَرْمَاهْ", "lt": "Hâdzâ wa qadis-taḥsanal-qiyâma ‘inda dzikri maulidihisy-syarîfi a'immatun dzawû riwâyatin wa rawiyyah, faṭûbâ liman kâna ta‘dhîmuhû shallallâhu ‘alaihi wa sallama ghâyata marâmihî wa marmâh", "id": "Berdiri ketika disebutkan kelahiran beliau yang mulia telah dianggap baik oleh para imam yang ahli riwayat dan pemikiran. Maka beruntunglah orang yang menjadikan pengagungan kepada beliau ﷺ sebagai puncak tujuan dan cita-citanya.", "no": 8},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 9}]},
{judul:"Wa Baraza: Peristiwa Saat Kelahiran",isi:[
{"ar": "وَبَرَزَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاضِعًا يَدَيْهِ عَلَى الْأَرْضِ رَافِعًا رَأْسَهُ إِلَى السَّمَاءِ الْعَلِيَّةْ، مُوْمِئًا بِذٰلِكَ الرَّفْعِ إِلَى سُؤْدَدِهِ وَعُلَاهْ", "lt": "Wa baraza shallallâhu ‘alaihi wa sallama wâdli‘an yadaihi ‘alal-ardli râfi‘an ra'sahû ilas-samâ'il-‘aliyyah, mûmi'an bidzâlikar-raf‘i ilâ su'dadihî wa ‘ulâh", "id": "Beliau ﷺ lahir dengan meletakkan kedua tangannya di atas bumi sambil mengangkat kepalanya ke langit yang tinggi, mengisyaratkan dengan tengadah itu kepemimpinan dan ketinggiannya,", "no": 1},
{"ar": "وَمُشِيْرًا إِلَى رِفْعَةِ قَدْرِهِ عَلَى سَائِرِ الْبَرِيَّةْ، وَأَنَّهُ الْحَبِيْبُ الَّذِيْ حَسُنَتْ طِبَاعُهُ وَسَجَايَاهْ", "lt": "Wa musyîran ilâ rif‘ati qadrihî ‘alâ sâ'iril-bariyyah, wa annahul-ḥabîbul-ladzî ḥasunat ṭibâ‘uhû wa sajâyâh", "id": "serta menunjukkan keluhuran derajatnya di atas seluruh makhluk, dan bahwa dialah kekasih yang indah tabiat dan perangainya.", "no": 2},
{"ar": "وَدَعَتْ أُمُّهُ عَبْدَ الْمُطَّلِبِ وَهُوَ يَطُوْفُ بِهَاتِيْكَ الْبَنِيَّةْ، فَأَقْبَلَ مُسْرِعًا وَنَظَرَ إِلَيْهِ وَبَلَغَ مِنَ السُّرُوْرِ مُنَاهْ", "lt": "Wa da‘at ummuhû ‘abdal-muṭṭalibi wa huwa yaṭûfu bihâtîkal-baniyyah, fa aqbala musri‘an wa nadhara ilaihi wa balagha minas-surûri munâh", "id": "Ibunya memanggil Abdul Muthalib yang sedang tawaf di Ka‘bah. Ia pun datang bergegas, memandang beliau, dan kegembiraannya mencapai puncak harapannya.", "no": 3},
{"ar": "وَأَدْخَلَهُ الْكَعْبَةَ الْغَرَّاءَ وَقَامَ يَدْعُوْ بِخُلُوْصِ النِّيَّةْ، وَيَشْكُرُ اللهَ تَعَالَى عَلَى مَا مَنَّ بِهِ عَلَيْهِ وَأَعْطَاهْ", "lt": "Wa adkhalahul-ka‘batal-gharrâ'a wa qâma yad‘û bikhulûshin-niyyah, wa yasykurullâha ta‘âlâ ‘alâ mâ manna bihî ‘alaihi wa a‘ṭâh", "id": "Ia membawanya masuk ke dalam Ka‘bah yang mulia, lalu berdiri berdoa dengan niat yang tulus, bersyukur kepada Allah Ta‘ala atas karunia dan pemberian-Nya kepadanya.", "no": 4},
{"ar": "وَوُلِدَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَظِيْفًا مَخْتُوْنًا مَقْطُوْعَ السُّرَّةِ بِيَدِ الْقُدْرَةِ الْإِلٰهِيَّةْ، طَيِّبًا دَهِيْنًا مَكْحُوْلَةً بِكُحْلِ الْعِنَايَةِ عَيْنَاهْ", "lt": "Wa wulida shallallâhu ‘alaihi wa sallama nadhîfan makhtûnan maqṭû‘as-surrati biyadil-qudratil-ilâhiyyah, ṭayyiban dahînan makḥûlatan bikuḥlil-‘inâyati ‘ainâh", "id": "Beliau ﷺ lahir dalam keadaan bersih, telah dikhitan, dan terpotong tali pusarnya oleh tangan kekuasaan Ilahi; harum, berminyak, dan kedua matanya bercelak dengan celak pemeliharaan (Allah).", "no": 5},
{"ar": "وَقِيْلَ خَتَنَهُ جَدُّهُ عَبْدُ الْمُطَّلِبِ بَعْدَ سَبْعِ لَيَالٍ سَوِيَّةْ، وَأَوْلَمَ وَأَطْعَمَ وَسَمَّاهُ مُحَمَّدًا وَأَكْرَمَ مَثْوَاهْ", "lt": "Wa qîla khatanahû jadduhû ‘abdul-muṭṭalibi ba‘da sab‘i layâlin sawiyyah, wa aulama wa aṭ‘ama wa sammâhu muḥammadan wa akrama matswâh", "id": "Ada yang mengatakan bahwa kakeknya, Abdul Muthalib, mengkhitannya setelah genap tujuh malam, lalu ia mengadakan walimah, memberi makan (orang banyak), menamainya Muhammad, dan memuliakan tempat tinggalnya.", "no": 6},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 7}]},
{judul:"Keajaiban Saat Kelahiran",isi:[
{"ar": "وَظَهَرَ عِنْدَ وِلَادَتِهِ خَوَارِقُ وَغَرَائِبُ غَيْبِيَّةْ، إِرْهَاصًا لِنُبُوَّتِهِ وَإِعْلَامًا بِأَنَّهُ مُخْتَارُ اللهِ تَعَالَى وَمُجْتَبَاهْ", "lt": "Wa dhahara ‘inda wilâdatihî khawâriqu wa gharâ'ibu ghaibiyyah, irhâshan linubuwwatihî wa i‘lâman bi'annahû mukhtârullâhi ta‘âlâ wa mujtabâh", "id": "Saat kelahirannya tampak berbagai peristiwa luar biasa dan keajaiban gaib, sebagai tanda awal kenabiannya dan pemberitahuan bahwa beliau adalah pilihan Allah Ta‘ala dan orang yang dipilih-Nya.", "no": 1},
{"ar": "فَزِيْدَتِ السَّمَاءُ حِفْظًا وَرُدَّ عَنْهَا الْمَرَدَةُ وَذَوُو النُّفُوْسِ الشَّيْطَانِيَّةْ، وَرَجَمَتِ النُّجُوْمُ النَّيِّرَاتُ كُلَّ رَجِيْمٍ فِيْ حَالِ مَرْقَاهْ", "lt": "Fazîdatis-samâ'u ḥifdhan wa rudda ‘anhal-maradatu wa dzawun-nufûsisy-syaiṭâniyyah, wa rajamatin-nujûmun-nayyirâtu kulla rajîmin fî ḥâli marqâh", "id": "Penjagaan langit ditambah, para pembangkang dan yang berjiwa setan diusir darinya, dan bintang-bintang yang bersinar melempari setiap setan terkutuk saat ia hendak naik.", "no": 2},
{"ar": "وَتَدَلَّتْ إِلَيْهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْأَنْجُمُ الزُّهْرِيَّةْ، وَاسْتَنَارَتْ بِنُوْرِهَا وِهَادُ الْحَرَمِ وَرُبَاهْ", "lt": "Wa tadallat ilaihi shallallâhu ‘alaihi wa sallamal-anjumuz-zuhriyyah, wastanârat binûrihâ wihâdul-ḥarami wa rubâh", "id": "Bintang-bintang yang cemerlang merendah mendekati beliau ﷺ, dan lembah-lembah serta bukit-bukit tanah haram menjadi terang oleh cahayanya.", "no": 3},
{"ar": "وَخَرَجَ مَعَهُ نُوْرٌ أَضَاءَتْ لَهُ قُصُوْرُ الشَّامِ الْقَيْصَرِيَّةْ، فَرَآهَا مَنْ بِبِطَاحِ مَكَّةَ دَارُهُ وَمَغْنَاهْ", "lt": "Wa kharaja ma‘ahû nûrun adlâ'at lahû qushûrusy-syâmil-qaishariyyah, fara'âhâ man bibiṭâḥi makkata dâruhû wa maghnâh", "id": "Bersamaan dengan kelahirannya keluar cahaya yang menerangi istana-istana Kaisar di Syam, hingga orang yang tinggal di lembah Makkah dapat melihatnya.", "no": 4},
{"ar": "وَانْصَدَعَ الْإِيْوَانُ بِالْمَدَائِنِ الْكِسْرَوِيَّةْ، الَّذِيْ رَفَعَ أَنُوْشِرْوَانُ سَمْكَهُ وَسَوَّاهْ", "lt": "Wanshada‘al-îwânu bil-madâ'inil-kisrawiyyah, al-ladzî rafa‘a anûsyirwânu samkahû wa sawwâh", "id": "Retaklah istana Kisra di kota Mada'in, yang atapnya telah ditinggikan dan disempurnakan oleh Anusyirwan.", "no": 5},
{"ar": "وَسَقَطَ أَرْبَعَ عَشْرَةَ مِنْ شُرُفَاتِهِ الْعُلْوِيَّةْ، وَكُسِرَ مُلْكُ كِسْرَى لِهَوْلِ مَا أَصَابَهُ وَعَرَاهْ", "lt": "Wa saqaṭa arba‘a ‘asyrata min syurufâtihil-‘ulwiyyah, wa kusira mulku kisrâ lihauli mâ ashâbahû wa ‘arâh", "id": "Empat belas balkonnya yang tinggi runtuh, dan kerajaan Kisra hancur karena dahsyatnya bencana yang menimpanya.", "no": 6},
{"ar": "وَخَمَدَتِ النِّيْرَانُ الْمَعْبُوْدَةُ بِالْمَمَالِكِ الْفَارِسِيَّةْ، لِطُلُوْعِ بَدْرِهِ الْمُنِيْرِ وَإِشْرَاقِ مُحَيَّاهْ", "lt": "Wa khamadatin-nîrânul-ma‘bûdatu bil-mamâlikil-fârisiyyah, liṭulû‘i badrihil-munîri wa isyrâqi muḥayyâh", "id": "Padamlah api-api sesembahan di kerajaan Persia, karena terbitnya purnama beliau yang bersinar dan wajahnya yang bercahaya.", "no": 7},
{"ar": "وَغَاضَتْ بُحَيْرَةُ سَاوَةَ وَكَانَتْ بَيْنَ هَمَذَانَ وَقُمٍّ مِنَ الْبِلَادِ الْعَجَمِيَّةْ، وَجَفَّتْ إِذْ كَفَّ وَاكِفُ مَوْجِهَا الثَّجَّاجِ يَنَابِيْعُ هَاتِيْكَ الْمِيَاهْ", "lt": "Wa ghâdlat buḥairatu sâwata wa kânat baina hamadzâna wa qummin minal-bilâdil-‘ajamiyyah, wa jaffat idz kaffa wâkifu maujihats-tsajjâji yanâbî‘u hâtîkal-miyâh", "id": "Danau Sawah yang terletak di antara Hamadzan dan Qum di negeri Persia menjadi surut; mata air-matanya kering ketika gelombangnya yang deras berhenti mengalir.", "no": 8},
{"ar": "وَفَاضَ وَادِيْ سَمَاوَةَ وَهِيَ مَفَازَةٌ فِيْ فَلَاةٍ وَبَرِيَّةْ، لَمْ يَكُنْ بِهَا مِنْ قَبْلُ يَنْقَعُ لِلظِّمَاءِ اللَّهَاهْ", "lt": "Wa fâdla wâdî samâwata wa hiya mafâzatun fî falâtin wa bariyyah, lam yakun bihâ min qablu yanqa‘u lidh-dhimâ'il-lahâh", "id": "Sebaliknya, lembah Samawah yang berupa padang tandus di tengah gurun justru meluap airnya, padahal sebelumnya tak ada air di sana yang dapat membasahi kerongkongan orang yang haus.", "no": 9},
{"ar": "وَكَانَ مَوْلِدُهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَوْضِعِ الْمَعْرُوْفِ بِالْعِرَاصِ الْمَكِّيَّةْ، وَالْبَلَدِ الَّذِيْ لَا يُعْضَدُ شَجَرُهُ وَلَا يُخْتَلَى خَلَاهْ", "lt": "Wa kâna mauliduhû shallallâhu ‘alaihi wa sallama bil-maudli‘il-ma‘rûfi bil-‘irâshil-makkiyyah, wal-baladil-ladzî lâ yu‘dladu syajaruhû wa lâ yukhtalâ khalâh", "id": "Kelahiran beliau ﷺ terjadi di tempat yang dikenal di pelataran Makkah, negeri yang pohonnya tidak boleh ditebang dan rumputnya tidak boleh dicabut.", "no": 10},
{"ar": "وَاخْتُلِفَ فِيْ عَامِ وِلَادَتِهِ وَفِيْ شَهْرِهَا وَفِيْ يَوْمِهَا عَلَى أَقْوَالٍ لِلْعُلَمَاءِ مَرْوِيَّةْ، وَالرَّاجِحُ أَنَّهَا قُبَيْلَ فَجْرِ يَوْمِ الْاِثْنَيْنِ ثَانِيَ عَشَرَ شَهْرِ رَبِيْعٍ الْأَوَّلِ مِنْ عَامِ الْفِيْلِ الَّذِيْ صَدَّهُ اللهُ عَنِ الْحَرَمِ وَحَمَاهْ", "lt": "Wakhtulifa fî ‘âmi wilâdatihî wa fî syahrihâ wa fî yaumihâ ‘alâ aqwâlin lil-‘ulamâ'i marwiyyah, war-râjiḥu annahâ qubaila fajri yaumil-itsnaini tsâniya ‘asyara syahri rabî‘il-awwali min ‘âmil-fîlil-ladzî shaddahullâhu ‘anil-ḥarami wa ḥamâh", "id": "Para ulama berbeda pendapat tentang tahun, bulan, dan hari kelahirannya, dengan beberapa riwayat. Pendapat yang kuat adalah sesaat sebelum fajar hari Senin, tanggal dua belas Rabiul Awal, pada Tahun Gajah, yang Allah halau dari tanah haram dan Dia lindungi tanah haram darinya.", "no": 11},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 12}]},
{judul:"Masa Penyusuan",isi:[
{"ar": "وَأَرْضَعَتْهُ أُمُّهُ أَيَّامًا، ثُمَّ أَرْضَعَتْهُ ثُوَيْبَةُ الْأَسْلَمِيَّةْ، الَّتِيْ أَعْتَقَهَا أَبُوْ لَهَبٍ حِيْنَ وَافَتْهُ عِنْدَ مِيْلَادِهِ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ بِبُشْرَاهْ", "lt": "Wa ardla‘at-hu ummuhû ayyâmâ, tsumma ardla‘at-hu tsuwaibatul-aslamiyyah, al-latî a‘taqahâ abû lahabin ḥîna wâfat-hu ‘inda mîlâdihî ‘alaihish-shalâtu was-salâmu bibusyrâh", "id": "Ibunya menyusuinya selama beberapa hari, kemudian ia disusui oleh Tsuwaibah Al-Aslamiyyah, yang dimerdekakan oleh Abu Lahab ketika ia datang membawa kabar gembira kelahiran beliau ﷺ.", "no": 1},
{"ar": "فَأَرْضَعَتْهُ مَعَ ابْنِهَا مَسْرُوْحٍ وَأَبِيْ سَلَمَةَ وَهِيَ بِهِ حَفِيَّةْ، وَأَرْضَعَتْ قَبْلَهُ حَمْزَةَ الَّذِيْ حُمِدَ فِيْ نُصْرَةِ الدِّيْنِ سُرَاهْ", "lt": "Fa ardla‘at-hu ma‘abnihâ masrûḥin wa abî salamata wa hiya bihî ḥafiyyah, wa ardla‘at qablahû ḥamzatal-ladzî ḥumida fî nushratid-dîni surâh", "id": "Ia menyusuinya bersama putranya, Masruh, dan Abu Salamah dengan penuh kasih sayang. Sebelumnya ia telah menyusui Hamzah, yang terpuji perjuangannya dalam membela agama.", "no": 2},
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَبْعَثُ إِلَيْهَا مِنَ الْمَدِيْنَةِ بِصِلَةٍ وَكِسْوَةٍ هِيَ بِهَا حَرِيَّةْ، إِلَى أَنْ أَوْرَدَ هَيْكَلَهَا رَائِدُ الْمَنُوْنِ الضَّرِيْحَ وَوَارَاهْ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama yab‘atsu ilaihâ minal-madînati bishilatin wa kiswatin hiya bihâ ḥariyyah, ilâ an aurada haikalahâ râ'idul-manûnidl-dlarîḥa wa wârâh", "id": "Rasulullah ﷺ biasa mengirimkan kepadanya dari Madinah hadiah dan pakaian yang pantas untuknya, hingga maut membawa jasadnya ke liang kubur dan menguburkannya.", "no": 3},
{"ar": "قِيْلَ عَلَى دِيْنِ قَوْمِهَا الْفِئَةِ الْجَاهِلِيَّةْ، وَقِيْلَ أَسْلَمَتْ أَثْبَتَ الْخِلَافَ ابْنُ مَنْدَهْ وَحَكَاهْ", "lt": "Qîla ‘alâ dîni qaumihal-fi'atil-jâhiliyyah, wa qîla aslamat atsbatal-khilâfabnu mandah wa ḥakâh", "id": "Ada yang mengatakan ia wafat dalam agama kaumnya yang jahiliah, dan ada yang mengatakan ia telah masuk Islam. Ibnu Mandah menetapkan dan menceritakan perbedaan pendapat ini.", "no": 4},
{"ar": "ثُمَّ أَرْضَعَتْهُ الْفَتَاةُ حَلِيْمَةُ السَّعْدِيَّةْ، وَكَانَ قَدْ رَدَّ كُلُّ الْقَوْمِ ثَدْيَهَا لِفَقْرِهَا وَأَبَاهْ", "lt": "Tsumma ardla‘at-hul-fatâtu ḥalîmatus-sa‘diyyah, wa kâna qad radda kullul-qaumi tsadyahâ lifaqrihâ wa abâh", "id": "Kemudian beliau disusui oleh seorang wanita muda, Halimah As-Sa‘diyyah, yang air susunya telah ditolak oleh semua orang karena kemiskinannya.", "no": 5},
{"ar": "فَأَخْصَبَ عَيْشُهَا بَعْدَ الْمَحْلِ قَبْلَ الْعَشِيَّةْ، وَدَرَّ ثَدْيَاهَا بِدُرٍّ دَرٍّ أَلْبَنَهُ الْيَمِيْنُ مِنْهُمَا وَأَلْبَنَ الْآخَرُ أَخَاهْ", "lt": "Fa akhshaba ‘aisyuhâ ba‘dal-maḥli qablal-‘asyiyyah, wa darra tsadyâhâ bidurrin darrin albanahul-yamînu minhumâ wa albanal-âkharu akhâh", "id": "Maka kehidupannya menjadi subur setelah kekeringan, bahkan sebelum sore hari. Kedua payudaranya mengalirkan air susu yang melimpah; yang kanan menyusui beliau dan yang kiri menyusui saudara (susuan)nya.", "no": 6},
{"ar": "وَأَصْبَحَتْ بَعْدَ الْهُزَالِ وَالْفَقْرِ غَنِيَّةْ، وَسَمِنَتِ الشَّارِفُ لَدَيْهَا وَالشِّيَاهْ", "lt": "Wa ashbaḥat ba‘dal-huzâli wal-faqri ghaniyyah, wa saminatisy-syârifu ladaihâ wasy-syiyâh", "id": "Setelah kurus dan miskin, ia menjadi berkecukupan; unta tuanya dan kambing-kambingnya pun menjadi gemuk.", "no": 7},
{"ar": "وَانْجَابَ عَنْ جَانِبِهَا كُلُّ مُلِمَّةٍ وَرَزِيَّةْ، وَطَرَّزَ السَّعْدُ بُرْدَ عَيْشِهَا الْهَنِيِّ وَوَشَاهْ", "lt": "Wanjâba ‘an jânibihâ kullu mulimmatin wa raziyyah, wa ṭarrazas-sa‘du burda ‘aisyihal-haniyyi wa wasyâh", "id": "Lenyaplah darinya segala musibah dan bencana, dan kebahagiaan menyulam serta menghiasi kain kehidupannya yang menyenangkan.", "no": 8},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 9}]},
{judul:"Pembelahan Dada dan Kembali kepada Ibunda",isi:[
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَشِبُّ فِي الْيَوْمِ شَبَابَ الصَّبِيِّ فِي الشَّهْرِ بِعِنَايَةٍ رَبَّانِيَّةْ، فَقَامَ عَلَى قَدَمَيْهِ فِيْ ثَلَاثٍ وَمَشَى فِيْ خَمْسٍ، وَقَوِيَتْ فِيْ تِسْعٍ مِنَ الشُّهُوْرِ بِفَصِيْحِ النُّطْقِ قُوَاهْ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama yasyibbu fil-yaumi syabâbash-shabiyyi fisy-syahri bi‘inâyatin rabbâniyyah, faqâma ‘alâ qadamaihi fî tsalâtsin wa masyâ fî khams, wa qawiyat fî tis‘in minasy-syuhûri bifashîḥin-nuṭqi quwâh", "id": "Dengan pemeliharaan Tuhan, beliau ﷺ tumbuh dalam sehari seperti pertumbuhan bayi lain dalam sebulan. Beliau berdiri di atas kedua kakinya pada usia tiga bulan, berjalan pada usia lima bulan, dan pada usia sembilan bulan telah fasih berbicara.", "no": 1},
{"ar": "وَشَقَّ الْمَلَكَانِ صَدْرَهُ الشَّرِيْفَ لَدَيْهَا، وَأَخْرَجَا مِنْهُ عَلَقَةً دَمَوِيَّةْ، وَأَزَالَا مِنْهُ حَظَّ الشَّيْطَانِ وَبِالثَّلْجِ غَسَلَاهْ", "lt": "Wa syaqqal-malakâni shadrahusy-syarîfa ladaihâ, wa akhrajâ minhu ‘alaqatan damawiyyah, wa azâlâ minhu ḥadhdhasy-syaiṭâni wa bits-tsalji ghasalâh", "id": "Ketika berada di tempat Halimah, dua malaikat membelah dadanya yang mulia, mengeluarkan segumpal darah darinya, menghilangkan bagian setan darinya, dan mencucinya dengan salju.", "no": 2},
{"ar": "وَمَلَآهُ حِكْمَةً وَمَعَانِيَ إِيْمَانِيَّةْ، ثُمَّ خَاطَاهُ وَبِخَاتَمِ النُّبُوَّةِ خَتَمَاهْ", "lt": "Wa mala'âhu ḥikmatan wa ma‘âniya îmâniyyah, tsumma khâṭâhu wa bikhâtamin-nubuwwati khatamâh", "id": "Keduanya memenuhinya dengan hikmah dan makna-makna keimanan, kemudian menjahitnya dan mencapnya dengan cap kenabian.", "no": 3},
{"ar": "وَوَزَنَاهُ فَرَجَحَ بِأَلْفٍ مِنْ أُمَّتِهِ الْخَيْرِيَّةْ، وَنَشَأَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى أَكْمَلِ الْأَوْصَافِ مِنْ حَالِ صِبَاهْ", "lt": "Wa wazanâhu farajaḥa bi'alfin min ummatihil-khairiyyah, wa nasya'a shallallâhu ‘alaihi wa sallama ‘alâ akmalil-aushâfi min ḥâli shibâh", "id": "Keduanya menimbangnya, ternyata beliau lebih berat daripada seribu orang dari umatnya yang terbaik. Beliau ﷺ tumbuh dengan sifat-sifat paling sempurna sejak masa kecilnya.", "no": 4},
{"ar": "ثُمَّ رَدَّتْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى أُمِّهِ وَهِيَ بِهِ غَيْرُ سَخِيَّةْ، حَذَرًا مِنْ أَنْ يُصَابَ بِمُصَابٍ حَادِثٍ تَخْشَاهْ", "lt": "Tsumma raddat-hu shallallâhu ‘alaihi wa sallama ilâ ummihî wa hiya bihî ghairu sakhiyyah, ḥadzaran min an yushâba bimushâbin ḥâditsin takhsyâh", "id": "Kemudian Halimah mengembalikan beliau ﷺ kepada ibunya dengan berat hati, karena khawatir beliau tertimpa musibah yang ia takutkan.", "no": 5},
{"ar": "وَوَفَدَتْ عَلَيْهِ حَلِيْمَةُ فِيْ أَيَّامِ خَدِيْجَةَ السَّيِّدَةِ الْوَضِيَّةْ، فَحَبَاهَا مِنْ حِبَائِهِ الْوَافِرِ بِحِبَاهْ", "lt": "Wa wafadat ‘alaihi ḥalîmatu fî ayyâmi khadîjatas-sayyidatil-wadliyyah, faḥabâhâ min ḥibâ'ihil-wâfiri biḥibâh", "id": "Halimah pernah datang menemui beliau pada masa (pernikahan beliau dengan) Khadijah, wanita mulia yang berseri wajahnya, lalu beliau memberinya hadiah yang melimpah.", "no": 6},
{"ar": "وَقَدِمَتْ عَلَيْهِ يَوْمَ حُنَيْنٍ فَقَامَ إِلَيْهَا وَأَخَذَتْهُ الْأَرْيَحِيَّةْ، وَبَسَطَ لَهَا مِنْ رِدَائِهِ الشَّرِيْفِ بِسَاطَ بِرِّهِ وَنَدَاهْ", "lt": "Wa qadimat ‘alaihi yauma ḥunainin faqâma ilaihâ wa akhadzat-hul-aryaḥiyyah, wa basaṭa lahâ min ridâ'ihisy-syarîfi bisâṭa birrihî wa nadâh", "id": "Ia juga datang menemui beliau pada hari (Perang) Hunain. Beliau berdiri menyambutnya dengan penuh kegembiraan, dan membentangkan selendangnya yang mulia sebagai hamparan kebaikan dan kemurahannya.", "no": 7},
{"ar": "وَالصَّحِيْحُ أَنَّهَا أَسْلَمَتْ مَعَ زَوْجِهَا وَالْبَنِيْنَ وَالذُّرِّيَّةْ، وَقَدْ عَدَّهُمْ فِي الصَّحَابَةِ جَمْعٌ مِنْ ثِقَاتِ الرُّوَاهْ", "lt": "Wash-shaḥîḥu annahâ aslamat ma‘a zaujihâ wal-banîna wadz-dzurriyyah, wa qad ‘addahum fish-shaḥâbati jam‘un min tsiqâtir-ruwâh", "id": "Pendapat yang benar, Halimah masuk Islam bersama suami, anak-anak, dan keturunannya, dan sejumlah perawi terpercaya menggolongkan mereka sebagai sahabat.", "no": 8},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 9}]},
{judul:"Wafat Ibunda dan Perjalanan ke Syam",isi:[
{"ar": "وَلَمَّا بَلَغَ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ أَرْبَعَ سِنِيْنَ خَرَجَتْ بِهِ أُمُّهُ إِلَى الْمَدِيْنَةِ النَّبَوِيَّةْ، ثُمَّ عَادَتْ فَوَافَتْهَا بِالْأَبْوَاءِ أَوْ بِشِعْبِ الْحَجُوْنِ الْوَفَاهْ", "lt": "Wa lammâ balagha ‘alaihish-shalâtu was-salâmu arba‘a sinîna kharajat bihî ummuhû ilal-madînatin-nabawiyyah, tsumma ‘âdat fawâfat-hal-wafâtu bil-abwâ'i au bisyi‘bil-ḥajûn", "id": "Ketika beliau ﷺ berusia empat tahun, ibunya membawanya ke Madinah. Kemudian ia pulang, dan wafat menjemputnya di Abwa', atau (menurut riwayat lain) di lembah Hajun.", "no": 1},
{"ar": "فَحَمَلَتْهُ حَاضِنَتُهُ أُمُّ أَيْمَنَ الْحَبَشِيَّةْ، الَّتِيْ زَوَّجَهَا بَعْدُ مِنْ زَيْدِ بْنِ حَارِثَةَ مَوْلَاهْ", "lt": "Faḥamalat-hu ḥâdlinatuhû ummu aimanal-ḥabasyiyyah, al-latî zawwajahâ ba‘du min zaidibni ḥâritsata maulâh", "id": "Beliau lalu dibawa oleh pengasuhnya, Ummu Aiman dari Habasyah, yang kelak beliau nikahkan dengan Zaid bin Haritsah, maula beliau.", "no": 2},
{"ar": "وَأَدْخَلَتْهُ عَلَى جَدِّهِ عَبْدِ الْمُطَّلِبِ فَضَمَّهُ إِلَيْهِ وَرَقَّ لَهُ وَأَعْلَى رُقِيَّهْ، وَقَالَ: إِنَّ لِابْنِيْ هٰذَا لَشَأْنًا عَظِيْمًا، فَبَخٍ بَخٍ لِمَنْ وَقَّرَهُ وَوَالَاهْ", "lt": "Wa adkhalat-hu ‘alâ jaddihî ‘abdil-muṭṭalibi fadlammahû ilaihi wa raqqa lahû wa a‘lâ ruqiyyah, wa qâla: inna libnî hâdzâ lasya'nan ‘adhîmâ, fabakhin bakhin liman waqqarahû wa wâlâh", "id": "Ia membawanya kepada kakeknya, Abdul Muthalib, yang kemudian mendekapnya, menyayanginya, dan meninggikan kedudukannya. Ia berkata: Sesungguhnya cucuku ini akan memiliki kedudukan yang agung; maka beruntunglah orang yang menghormati dan membelanya.", "no": 3},
{"ar": "وَلَمْ تَشْكُ فِيْ صِبَاهُ جُوْعًا وَلَا عَطَشًا قَطُّ نَفْسُهُ الْأَبِيَّةْ، وَكَثِيْرًا مَا غَدَا فَاغْتَذَى بِمَاءِ زَمْزَمَ فَأَشْبَعَهُ وَأَرْوَاهْ", "lt": "Wa lam tasyku fî shibâhu jû‘an wa lâ ‘aṭasyan qaṭṭu nafsuhul-abiyyah, wa katsîran mâ ghadâ faghtadzâ bimâ'i zamzama fa asyba‘ahû wa arwâh", "id": "Semasa kecil, jiwanya yang mulia tak pernah mengeluh lapar ataupun haus. Sering kali di pagi hari beliau hanya meminum air Zamzam, dan air itu mengenyangkan serta menghilangkan dahaganya.", "no": 4},
{"ar": "وَلَمَّا أُنِيْخَتْ بِفِنَاءِ جَدِّهِ عَبْدِ الْمُطَّلِبِ مَطَايَا الْمَنِيَّةْ، كَفَلَهُ عَمُّهُ أَبُوْ طَالِبٍ شَقِيْقُ أَبِيْهِ عَبْدِ اللهْ", "lt": "Wa lammâ unîkhat bifinâ'i jaddihî ‘abdil-muṭṭalibi maṭâyal-maniyyah, kafalahû ‘ammuhû abû ṭâlibin syaqîqu abîhi ‘abdillâh", "id": "Ketika kendaraan maut berhenti di halaman kakeknya, Abdul Muthalib, beliau diasuh oleh pamannya, Abu Thalib, saudara kandung ayahnya, Abdullah.", "no": 5},
{"ar": "فَقَامَ بِكَفَالَتِهِ بِعَزْمٍ قَوِيٍّ وَهِمَّةٍ وَحَمِيَّةْ، وَقَدَّمَهُ عَلَى النَّفْسِ وَالْبَنِيْنَ وَرَبَّاهْ", "lt": "Faqâma bikafâlatihî bi‘azmin qawiyyin wa himmatin wa ḥamiyyah, wa qaddamahû ‘alan-nafsi wal-banîna wa rabbâh", "id": "Ia mengasuhnya dengan tekad yang kuat, semangat, dan pembelaan, mendahulukan beliau di atas dirinya sendiri dan anak-anaknya, serta mendidiknya.", "no": 6},
{"ar": "وَلَمَّا بَلَغَ اثْنَتَيْ عَشْرَةَ سَنَةً رَحَلَ بِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَمُّهُ أَبُوْ طَالِبٍ إِلَى الْبِلَادِ الشَّامِيَّةْ، وَعَرَفَهُ الرَّاهِبُ بَحِيْرَاءُ بِمَا حَازَهُ مِنْ وَصْفِ النُّبُوَّةِ وَحَوَاهْ", "lt": "Wa lammâ balaghatsnatai ‘asyrata sanatan raḥala bihî shallallâhu ‘alaihi wa sallama ‘ammuhû abû ṭâlibin ilal-bilâdisy-syâmiyyah, wa ‘arafahur-râhibu baḥîrâ'u bimâ ḥâzahû min washfin-nubuwwati wa ḥawâh", "id": "Ketika beliau berusia dua belas tahun, pamannya, Abu Thalib, membawa beliau ﷺ ke negeri Syam. Pendeta Bahira mengenali beliau melalui sifat-sifat kenabian yang terdapat pada dirinya.", "no": 7},
{"ar": "وَقَالَ: إِنِّيْ أَرَاهُ سَيِّدَ الْعَالَمِيْنَ وَرَسُوْلَ اللهِ وَنَبِيَّهْ، وَقَدْ سَجَدَ لَهُ الشَّجَرُ وَالْحَجَرُ وَلَا يَسْجُدَانِ إِلَّا لِنَبِيٍّ أَوَّاهْ", "lt": "Wa qâla: innî arâhu sayyidal-‘âlamîna wa rasûlallâhi wa nabiyyah, wa qad sajada lahusy-syajaru wal-ḥajaru wa lâ yasjudâni illâ linabiyyin awwâh", "id": "Ia berkata: Sungguh aku melihatnya sebagai pemimpin semesta alam, utusan Allah, dan nabi-Nya. Pohon dan batu telah bersujud kepadanya, padahal keduanya tidak bersujud kecuali kepada seorang nabi yang sangat tunduk kepada Allah.", "no": 8},
{"ar": "وَإِنَّا لَنَجِدُ نَعْتَهُ فِي الْكُتُبِ الْقَدِيْمَةِ السَّمَاوِيَّةْ، وَبَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ قَدْ عَمَّهُ النُّوْرُ وَعَلَاهْ", "lt": "Wa innâ lanajidu na‘tahû fil-kutubil-qadîmatis-samâwiyyah, wa baina katifaihi khâtamun-nubuwwati qad ‘ammahun-nûru wa ‘alâh", "id": "Sungguh kami mendapati sifat-sifatnya dalam kitab-kitab samawi terdahulu, dan di antara kedua bahunya terdapat cap kenabian yang diliputi dan dinaungi cahaya.", "no": 9},
{"ar": "وَأَمَرَ عَمَّهُ بِرَدِّهِ إِلَى مَكَّةَ تَخَوُّفًا عَلَيْهِ مِنْ أَهْلِ دِيْنِ الْيَهُوْدِيَّةْ، فَرَجَعَ بِهِ وَلَمْ يُجَاوِزْ مِنَ الشَّامِ الْمُقَدَّسِ بُصْرَاهْ", "lt": "Wa amara ‘ammahû biraddihî ilâ makkata takhawwufan ‘alaihi min ahli dînil-yahûdiyyah, faraja‘a bihî wa lam yujâwiz minasy-syâmil-muqaddasi bushrâh", "id": "Ia menyuruh pamannya untuk membawanya kembali ke Makkah karena khawatir akan (gangguan) para pemeluk agama Yahudi. Maka pamannya pulang bersamanya dan tidak melewati Bushra di negeri Syam yang disucikan.", "no": 10},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 11}]},
{judul:"Perniagaan ke Syam dan Pernikahan dengan Khadijah",isi:[
{"ar": "وَلَمَّا بَلَغَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَمْسًا وَعِشْرِيْنَ سَنَةً سَافَرَ إِلَى بُصْرَى فِيْ تِجَارَةٍ لِخَدِيْجَةَ الْفَتِيَّةْ، وَمَعَهُ غُلَامُهَا مَيْسَرَةُ يَخْدُمُهُ عَلَيْهِ الصَّلَاةُ وَالسَّلَامُ وَيَقُوْمُ بِمَا عَنَاهْ", "lt": "Wa lammâ balagha shallallâhu ‘alaihi wa sallama khamsan wa ‘isyrîna sanatan sâfara ilâ bushrâ fî tijâratin likhadîjatal-fatiyyah, wa ma‘ahû ghulâmuhâ maisaratu yakhdumuhû ‘alaihish-shalâtu was-salâmu wa yaqûmu bimâ ‘anâh", "id": "Ketika beliau ﷺ berusia dua puluh lima tahun, beliau pergi ke Bushra membawa barang dagangan milik Khadijah yang masih muda, ditemani budaknya, Maisarah, yang melayani beliau dan mengurus keperluannya.", "no": 1},
{"ar": "وَنَزَلَ تَحْتَ شَجَرَةٍ لَدَى صَوْمَعَةِ نُسْطُوْرَا رَاهِبِ النَّصْرَانِيَّةْ، فَعَرَفَهُ الرَّاهِبُ إِذْ مَالَ إِلَيْهِ ظِلُّهَا الْوَارِفُ وَآوَاهْ", "lt": "Wa nazala taḥta syajaratin ladâ shauma‘ati nusṭûrâ râhibin-nashrâniyyah, fa ‘arafahur-râhibu idz mâla ilaihi dhilluhal-wârifu wa âwâh", "id": "Beliau singgah di bawah sebatang pohon di dekat biara Nasthura, seorang rahib Nasrani. Rahib itu mengenali beliau ketika naungan pohon yang rindang condong kepadanya dan menaunginya.", "no": 2},
{"ar": "وَقَالَ: مَا نَزَلَ تَحْتَ هٰذِهِ الشَّجَرَةِ قَطُّ إِلَّا نَبِيٌّ ذُوْ صِفَاتٍ نَقِيَّةْ، وَرَسُوْلٌ قَدْ خَصَّهُ اللهُ تَعَالَى بِالْفَضَائِلِ وَحَبَاهْ", "lt": "Wa qâla: mâ nazala taḥta hâdzihisy-syajarati qaṭṭu illâ nabiyyun dzû shifâtin naqiyyah, wa rasûlun qad khash-shahullâhu ta‘âlâ bil-fadlâ'ili wa ḥabâh", "id": "Ia berkata: Tidak pernah ada yang singgah di bawah pohon ini kecuali seorang nabi yang memiliki sifat-sifat yang suci, dan rasul yang telah Allah Ta‘ala istimewakan dengan berbagai keutamaan dan anugerah.", "no": 3},
{"ar": "ثُمَّ قَالَ لِمَيْسَرَةَ: أَفِيْ عَيْنَيْهِ حُمْرَةٌ؟ اسْتِظْهَارًا لِلْعَلَامَةِ الْخَفِيَّةْ، فَأَجَابَهُ بِنَعَمْ فَحَقَّ لَدَيْهِ مَا ظَنَّهُ فِيْهِ وَتَوَخَّاهْ", "lt": "Tsumma qâla limaisarah: afî ‘ainaihi ḥumrah? istidh-hâran lil-‘alâmatil-khafiyyah, fa ajâbahû bina‘am faḥaqqa ladaihi mâ dhannahû fîhi wa tawakhkhâh", "id": "Kemudian ia bertanya kepada Maisarah untuk memastikan tanda yang tersembunyi: Apakah di kedua matanya ada warna kemerahan? Maisarah menjawab: Ya. Maka benarlah apa yang ia sangka dan ia cari pada diri beliau.", "no": 4},
{"ar": "ثُمَّ قَالَ لِمَيْسَرَةَ: لَا تُفَارِقْهُ وَكُنْ مَعَهُ بِصِدْقٍ وَعَزْمٍ وَحُسْنِ طَوِيَّةْ، فَإِنَّهُ مِمَّنْ أَكْرَمَهُ اللهُ تَعَالَى بِالنُّبُوَّةِ وَاجْتَبَاهْ", "lt": "Tsumma qâla limaisarah: lâ tufâriqhu wa kun ma‘ahû bishidqin wa ‘azmin wa ḥusni ṭawiyyah, fa innahû mimman akramahullâhu ta‘âlâ bin-nubuwwati wajtabâh", "id": "Lalu ia berkata kepada Maisarah: Jangan berpisah darinya, dan temanilah ia dengan kejujuran, kesungguhan, dan niat yang baik, karena sesungguhnya ia termasuk orang yang dimuliakan Allah Ta‘ala dengan kenabian dan dipilih-Nya.", "no": 5},
{"ar": "ثُمَّ عَادَ إِلَى مَكَّةَ فَرَأَتْهُ خَدِيْجَةُ مُقْبِلًا وَهِيَ بَيْنَ نِسْوَةٍ فِيْ عِلِّيَّةْ، وَمَلَكَانِ عَلَى رَأْسِهِ الشَّرِيْفِ مِنْ وَهَجِ الشَّمْسِ قَدْ أَظَلَّاهْ", "lt": "Tsumma ‘âda ilâ makkata fara'at-hu khadîjatu muqbilan wa hiya baina niswatin fî ‘illiyyah, wa malakâni ‘alâ ra'sihisy-syarîfi min wahajisy-syamsi qad adhallâh", "id": "Kemudian beliau kembali ke Makkah. Khadijah, yang sedang berada di loteng bersama para wanita, melihat beliau datang, sementara dua malaikat menaungi kepalanya yang mulia dari teriknya matahari.", "no": 6},
{"ar": "وَأَخْبَرَهَا مَيْسَرَةُ بِأَنَّهُ رَأَى ذٰلِكَ فِي السَّفَرِ كُلِّهِ، وَبِمَا قَالَهُ الرَّاهِبُ وَأَوْدَعَهُ لَدَيْهِ مِنَ الْوَصِيَّةْ، وَضَاعَفَ اللهُ تَعَالَى فِيْ تِلْكَ التِّجَارَةِ رِبْحَهَا وَنَمَّاهْ", "lt": "Wa akhbarahâ maisaratu bi'annahû ra'â dzâlika fis-safari kullih, wa bimâ qâlahur-râhibu wa auda‘ahû ladaihi minal-washiyyah, wa dlâ‘afallâhu ta‘âlâ fî tilkat-tijârati ribḥahâ wa nammâh", "id": "Maisarah memberitahunya bahwa ia telah melihat hal itu sepanjang perjalanan, juga tentang ucapan dan pesan sang rahib kepadanya. Allah Ta‘ala melipatgandakan keuntungan perniagaan itu dan mengembangkannya.", "no": 7},
{"ar": "فَبَانَ لِخَدِيْجَةَ بِمَا رَأَتْ وَمَا سَمِعَتْ أَنَّهُ رَسُوْلُ اللهِ تَعَالَى إِلَى الْبَرِيَّةْ، الَّذِيْ خَصَّهُ اللهُ تَعَالَى بِقُرْبِهِ وَاصْطَفَاهْ", "lt": "Fabâna likhadîjata bimâ ra'at wa mâ sami‘at annahû rasûlullâhi ta‘âlâ ilal-bariyyah, al-ladzî khash-shahullâhu ta‘âlâ biqurbihî washṭafâh", "id": "Dari apa yang ia lihat dan dengar, jelaslah bagi Khadijah bahwa beliau adalah utusan Allah Ta‘ala kepada seluruh makhluk, yang Allah Ta‘ala istimewakan dengan kedekatan-Nya dan Dia pilih.", "no": 8},
{"ar": "فَخَطَبَتْهُ لِنَفْسِهَا الزَّكِيَّةْ، لِتَشُمَّ مِنَ الْإِيْمَانِ بِهِ طِيْبَ رَيَّاهْ", "lt": "Fakhaṭabat-hu linafsihaz-zakiyyah, litasyumma minal-îmâni bihî ṭîba rayyâh", "id": "Maka ia melamar beliau untuk dirinya yang suci, agar ia dapat mencium harumnya keimanan kepada beliau.", "no": 9},
{"ar": "فَأَخْبَرَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْمَامَهُ بِمَا دَعَتْهُ إِلَيْهِ هٰذِهِ الْبَرَّةُ التَّقِيَّةْ، فَرَغِبُوْا فِيْهَا لِفَضْلٍ وَدِيْنٍ وَجَمَالٍ وَمَالٍ وَحَسَبٍ وَنَسَبٍ كُلٌّ مِنَ الْقَوْمِ يَهْوَاهْ", "lt": "Fa akhbara shallallâhu ‘alaihi wa sallama a‘mâmahû bimâ da‘at-hu ilaihi hâdzihil-barratut-taqiyyah, faraghibû fîhâ lifadllin wa dînin wa jamâlin wa mâlin wa ḥasabin wa nasabin kullun minal-qaumi yahwâh", "id": "Beliau ﷺ memberitahukan kepada paman-pamannya tentang ajakan wanita yang baik lagi bertakwa itu. Mereka pun menyukainya karena keutamaan, agama, kecantikan, harta, kehormatan, dan nasabnya, yang semuanya didambakan setiap orang.", "no": 10},
{"ar": "وَخَطَبَ أَبُوْ طَالِبٍ وَأَثْنَى عَلَيْهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْدَ أَنْ حَمِدَ اللهَ بِمَحَامِدَ سَنِيَّةْ، وَقَالَ: هُوَ وَاللهِ لَهُ نَبَأٌ عَظِيْمٌ يُحْمَدُ فِيْهِ مَسْرَاهْ", "lt": "Wa khaṭaba abû ṭâlibin wa atsnâ ‘alaihi shallallâhu ‘alaihi wa sallama ba‘da an ḥamidallâha bimaḥâmida saniyyah, wa qâla: huwa wallâhi lahû naba'un ‘adhîmun yuḥmadu fîhi masrâh", "id": "Abu Thalib menyampaikan khutbah (nikah) dan memuji beliau ﷺ setelah memuji Allah dengan pujian-pujian yang luhur. Ia berkata: Demi Allah, dia akan memiliki berita besar yang perjalanannya akan terpuji.", "no": 11},
{"ar": "فَزَوَّجَهَا مِنْهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَبُوْهَا، وَقِيْلَ عَمُّهَا، وَقِيْلَ أَخُوْهَا لِسَابِقِ سَعَادَتِهَا الْأَزَلِيَّةْ، وَأَوْلَدَهَا كُلَّ أَوْلَادِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا الَّذِيْ بِاسْمِ الْخَلِيْلِ سَمَّاهْ", "lt": "Fazawwajahâ minhu shallallâhu ‘alaihi wa sallama abûhâ, wa qîla ‘ammuhâ, wa qîla akhûhâ lisâbiqi sa‘âdatihal-azaliyyah, wa auladahâ kulla aulâdihî shallallâhu ‘alaihi wa sallama illal-ladzî bismil-khalîli sammâh", "id": "Maka ayahnya, atau menurut riwayat lain pamannya atau saudaranya, menikahkannya dengan beliau ﷺ, karena telah tertulis kebahagiaannya sejak azali. Dari Khadijah lahir seluruh putra-putri beliau ﷺ, kecuali putra yang beliau namai dengan nama Al-Khalil (Ibrahim).", "no": 12},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 13}]},
{judul:"Peletakan Hajar Aswad",isi:[
{"ar": "وَلَمَّا بَلَغَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَمْسًا وَثَلَاثِيْنَ سَنَةً، بَنَتْ قُرَيْشٌ الْكَعْبَةَ لِانْصِدَاعِهَا بِالسُّيُوْلِ الْأَبْطَحِيَّةْ، وَتَنَازَعُوْا فِيْ رَفْعِ الْحَجَرِ الْأَسْوَدِ فَكُلٌّ أَرَادَ رَفْعَهُ وَرَجَاهْ", "lt": "Wa lammâ balagha shallallâhu ‘alaihi wa sallama khamsan wa tsalâtsîna sanah, banat quraisyunil-ka‘bata linshidâ‘ihâ bis-suyûlil-abṭaḥiyyah, wa tanâza‘û fî raf‘il-ḥajaril-aswadi fakullun arâda raf‘ahû wa rajâh", "id": "Ketika beliau ﷺ berusia tiga puluh lima tahun, kaum Quraisy membangun kembali Ka‘bah yang retak karena banjir di lembah Makkah. Mereka berselisih tentang siapa yang mengangkat Hajar Aswad, karena setiap kabilah ingin dan berharap dapat mengangkatnya.", "no": 1},
{"ar": "وَعَظُمَ الْقِيْلُ وَالْقَالُ وَتَحَالَفُوْا عَلَى الْقِتَالِ وَقَوِيَتِ الْعَصَبِيَّةْ، ثُمَّ تَدَاعَوْا إِلَى الْإِنْصَافِ وَفَوَّضُوا الْأَمْرَ إِلَى ذِيْ رَأْيٍ صَائِبٍ وَأَنَاهْ", "lt": "Wa ‘adhumal-qîlu wal-qâlu wa taḥâlafû ‘alal-qitâli wa qawiyatil-‘ashabiyyah, tsumma tadâ‘au ilal-inshâfi wa fawwadlul-amra ilâ dzî ra'yin shâ'ibin wa anâh", "id": "Perdebatan semakin memanas, mereka bersumpah untuk berperang, dan fanatisme kesukuan semakin kuat. Kemudian mereka saling mengajak untuk bersikap adil dan menyerahkan urusan itu kepada orang yang berpendapat tepat dan bijaksana.", "no": 2},
{"ar": "فَحَكَمَ بِتَحْكِيْمِ أَوَّلِ دَاخِلٍ مِنْ بَابِ السَّدَنَةِ الشَّيْبِيَّةْ، فَكَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَوَّلَ دَاخِلٍ، فَقَالُوْا: هٰذَا الْأَمِيْنُ وَكُلُّنَا نَقْبَلُهُ وَنَرْضَاهْ", "lt": "Faḥakama bitaḥkîmi awwali dâkhilin min bâbis-sadanatisy-syaibiyyah, fakânan-nabiyyu shallallâhu ‘alaihi wa sallama awwala dâkhil, faqâlû: hâdzal-amînu wa kullunâ naqbaluhû wa nardlâh", "id": "Ia memutuskan agar orang pertama yang masuk dari pintu Bani Syaibah, penjaga Ka‘bah, menjadi hakim. Ternyata Nabi ﷺ adalah orang pertama yang masuk. Mereka berkata: Inilah Al-Amin (orang yang terpercaya), kami semua menerima dan rela kepadanya.", "no": 3},
{"ar": "فَأَخْبَرُوْهُ بِأَنَّهُمْ رَضُوْهُ أَنْ يَكُوْنَ صَاحِبَ الْحُكْمِ فِيْ هٰذَا الْمُهِمِّ وَوَلِيَّهْ، فَوَضَعَ الْحَجَرَ فِيْ ثَوْبٍ ثُمَّ أَمَرَ أَنْ تَرْفَعَهُ الْقَبَائِلُ جَمِيْعًا إِلَى مُرْتَقَاهْ", "lt": "Fa akhbarûhu bi'annahum radlûhu an yakûna shâḥibal-ḥukmi fî hâdzal-muhimmi wa waliyyah, fawadla‘al-ḥajara fî tsaubin tsumma amara an tarfa‘ahul-qabâ'ilu jamî‘an ilâ murtaqâh", "id": "Mereka memberitahu beliau bahwa mereka rela beliau menjadi hakim dan pengurus dalam perkara penting ini. Maka beliau meletakkan Hajar Aswad di atas sehelai kain, lalu memerintahkan seluruh kabilah untuk mengangkatnya bersama-sama ke tempatnya.", "no": 4},
{"ar": "فَرَفَعُوْهُ إِلَى مَقَرِّهِ مِنْ رُكْنِ هَاتِيْكَ الْبَنِيَّةْ، وَوَضَعَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ الشَّرِيْفَةِ فِيْ مَوْضِعِهِ الْآنَ وَبَنَاهْ", "lt": "Farafa‘ûhu ilâ maqarrihî min rukni hâtîkal-baniyyah, wa wadla‘ahû shallallâhu ‘alaihi wa sallama biyadihisy-syarîfati fî maudli‘ihil-âna wa banâh", "id": "Mereka mengangkatnya ke tempatnya di sudut bangunan Ka‘bah itu, lalu beliau ﷺ meletakkannya dengan tangannya yang mulia di tempatnya yang sekarang dan membangun (dinding) di atasnya.", "no": 5},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 6}]},
{judul:"Diutus Menjadi Rasul",isi:[
{"ar": "وَلَمَّا كَمُلَ لَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَرْبَعُوْنَ سَنَةً عَلَى أَوْفَقِ الْأَقْوَالِ لِذَوِي الْعَالِمِيَّةْ، بَعَثَهُ اللهُ تَعَالَى لِلْعَالَمِيْنَ بَشِيْرًا وَنَذِيْرًا فَعَمَّهُمْ بِرُحْمَاهْ", "lt": "Wa lammâ kamula lahû shallallâhu ‘alaihi wa sallama arba‘ûna sanatan ‘alâ aufaqil-aqwâli lidzawil-‘âlimiyyah, ba‘atsahullâhu ta‘âlâ lil-‘âlamîna basyîran wa nadzîran fa‘ammahum biruḥmâh", "id": "Ketika usia beliau ﷺ genap empat puluh tahun, menurut pendapat yang paling sesuai di kalangan ulama, Allah Ta‘ala mengutusnya kepada seluruh alam sebagai pembawa kabar gembira dan pemberi peringatan, maka rahmatnya meliputi mereka semua.", "no": 1},
{"ar": "وَبُدِئَ إِلَى تَمَامِ سِتَّةِ أَشْهُرٍ بِالرُّؤْيَا الصَّادِقَةِ الْجَلِيَّةْ، فَكَانَ لَا يَرَى رُؤْيَا إِلَّا جَاءَتْ مِثْلَ فَلَقِ صُبْحٍ أَضَاءَ سَنَاهْ", "lt": "Wa budi'a ilâ tamâmi sittati asyhurin bir-ru'yâsh-shâdiqatil-jaliyyah, fakâna lâ yarâ ru'yâ illâ jâ'at mitsla falaqi shubḥin adlâ'a sanâh", "id": "Wahyu dimulai dengan mimpi yang benar dan jelas selama enam bulan; tidaklah beliau bermimpi kecuali mimpi itu datang (menjadi kenyataan) seperti terbitnya fajar yang terang sinarnya.", "no": 2},
{"ar": "وَإِنَّمَا ابْتُدِئَ بِالرُّؤْيَا تَمْرِيْنًا لِلْقُوَّةِ الْبَشَرِيَّةْ، لِئَلَّا يَفْجَأَهُ الْمَلَكُ بِصَرِيْحِ النُّبُوَّةِ فَلَا تَقْوَاهُ قُوَاهْ", "lt": "Wa innamabtudi'a bir-ru'yâ tamrînan lil-quwwatil-basyariyyah, li'allâ yafja'ahul-malaku bisharîḥin-nubuwwati falâ taqwâhu quwâh", "id": "Wahyu diawali dengan mimpi semata-mata untuk melatih kekuatan manusiawinya, agar malaikat tidak datang tiba-tiba membawa kenabian secara terang-terangan sehingga kekuatannya tidak sanggup menanggungnya.", "no": 3},
{"ar": "وَحُبِّبَ إِلَيْهِ الْخَلَاءُ فَكَانَ يَتَعَبَّدُ بِحِرَاءٍ اللَّيَالِيَ الْعَدَدِيَّةْ، إِلَى أَنْ أَتَاهُ فِيْهِ صَرِيْحُ الْحَقِّ وَوَافَاهْ", "lt": "Wa ḥubbiba ilaihil-khalâ'u fakâna yata‘abbadu biḥirâ'in al-layâliyal-‘adadiyyah, ilâ an atâhu fîhi sharîḥul-ḥaqqi wa wâfâh", "id": "Beliau dijadikan senang menyendiri, maka beliau beribadah di Gua Hira beberapa malam, hingga datang kepadanya kebenaran yang nyata di sana.", "no": 4},
{"ar": "وَذٰلِكَ فِيْ يَوْمِ الْاِثْنَيْنِ لِسَبْعَ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ شَهْرِ اللَّيْلَةِ الْقَدْرِيَّةْ، وَثَمَّ أَقْوَالٌ لِسَبْعٍ أَوْ لِأَرْبَعٍ وَعِشْرِيْنَ مِنْهُ أَوْ لِثَمَانٍ خَلَتْ مِنْ شَهْرِ مَوْلِدِهِ الَّذِيْ بَدَا فِيْهِ بَدْرُ مُحَيَّاهْ", "lt": "Wa dzâlika fî yaumil-itsnaini lisab‘a ‘asyrata lailatan khalat min syahril-lailatil-qadriyyah, wa tsamma aqwâlun lisab‘in au li'arba‘in wa ‘isyrîna minhu au litsamânin khalat min syahri maulidihil-ladzî badâ fîhi badru muḥayyâh", "id": "Hal itu terjadi pada hari Senin, tanggal tujuh belas bulan yang di dalamnya ada Lailatul Qadar (Ramadhan). Ada pula pendapat lain: tanggal tujuh atau dua puluh empat (Ramadhan), atau tanggal delapan bulan kelahirannya, saat purnama wajahnya terbit.", "no": 5},
{"ar": "فَقَالَ لَهُ: اقْرَأْ، فَأَبَى، فَغَطَّهُ غَطَّةً قَوِيَّةْ، ثُمَّ قَالَ لَهُ: اقْرَأْ، فَأَبَى، فَغَطَّهُ ثَانِيَةً حَتَّى بَلَغَ مِنْهُ الْجَهْدُ وَغَطَّاهْ", "lt": "Faqâla lahuq-ra', fa abâ, faghaṭṭahû ghaṭṭatan qawiyyah, tsumma qâla lahuq-ra', fa abâ, faghaṭṭahû tsâniyatan ḥattâ balagha minhul-jahdu wa ghaṭṭâh", "id": "Jibril berkata kepadanya: Bacalah! Beliau menolak (karena tidak bisa membaca), maka Jibril mendekapnya dengan kuat. Kemudian ia berkata: Bacalah! Beliau menolak lagi, maka Jibril mendekapnya untuk kedua kalinya hingga beliau merasa sangat payah.", "no": 6},
{"ar": "ثُمَّ قَالَ لَهُ: اقْرَأْ، فَأَبَى، فَغَطَّهُ ثَالِثَةً لِيَتَوَجَّهَ إِلَى مَا سَيُلْقَى إِلَيْهِ بِجَمْعِيَّةْ، وَيُقَابِلَهُ بِجِدٍّ وَاجْتِهَادٍ وَيَتَلَقَّاهْ", "lt": "Tsumma qâla lahuq-ra', fa abâ, faghaṭṭahû tsâlitsatan liyatawajjaha ilâ mâ sayulqâ ilaihi bijam‘iyyah, wa yuqâbilahû bijiddin wajtihâdin wa yatalaqqâh", "id": "Lalu ia berkata lagi: Bacalah! Beliau menolak, maka Jibril mendekapnya untuk ketiga kalinya, agar beliau menghadap dengan segenap jiwa kepada apa yang akan disampaikan kepadanya, serta menyambut dan menerimanya dengan sungguh-sungguh.", "no": 7},
{"ar": "ثُمَّ فَتَرَ الْوَحْيُ ثَلَاثَ سِنِيْنَ أَوْ ثَلَاثِيْنَ شَهْرًا، لِيَشْتَاقَ إِلَى انْتِشَاقِ هَاتِيْكَ النَّفَحَاتِ الشَّذِيَّةْ، ثُمَّ أُنْزِلَتْ عَلَيْهِ (يَا أَيُّهَا الْمُدَّثِّرُ) فَجَاءَهُ جِبْرِيْلُ بِهَا وَنَادَاهْ", "lt": "Tsumma fataral-waḥyu tsalâtsa sinîna au tsalâtsîna syahran, liyasytâqa ilantisyâqi hâtîkan-nafaḥâtisy-syadziyyah, tsumma unzilat ‘alaihi (yâ ayyuhal-muddatstsir) fajâ'ahû jibrîlu bihâ wa nâdâh", "id": "Kemudian wahyu terhenti selama tiga tahun atau tiga puluh bulan, agar beliau rindu menghirup embusan-embusan wahyu yang harum itu. Lalu diturunkan kepadanya (Yâ ayyuhal-muddatstsir), dibawa oleh Jibril yang menyerunya.", "no": 8},
{"ar": "فَكَانَ لِنُبُوَّتِهِ فِيْ تَقَدُّمِ (اقْرَأْ بِاسْمِ رَبِّكَ) شَاهِدٌ عَلَى أَنَّ لَهَا السَّابِقِيَّةْ، وَالتَّقَدُّمَ عَلَى رِسَالَتِهِ بِالْبِشَارَةِ وَالنِّذَارَةِ لِمَنْ دَعَاهْ", "lt": "Fakâna linubuwwatihî fî taqaddumi (iqra' bismi rabbik) syâhidun ‘alâ anna lahas-sâbiqiyyah, wat-taqaddumu ‘alâ risâlatihî bil-bisyârati wan-nidzârati liman da‘âh", "id": "Turunnya (Iqra' bismi rabbik) lebih dahulu menjadi bukti bahwa kenabian beliau lebih dahulu datang, mendahului kerasulannya yang membawa kabar gembira dan peringatan kepada orang yang beliau seru.", "no": 9},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 10}]},
{judul:"Orang-orang Pertama yang Beriman",isi:[
{"ar": "وَأَوَّلُ مَنْ آمَنَ بِهِ مِنَ الرِّجَالِ أَبُوْ بَكْرٍ صَاحِبُ الْغَارِ وَالصِّدِّيْقِيَّةْ، وَمِنَ الصِّبْيَانِ عَلِيٌّ، وَمِنَ النِّسَاءِ خَدِيْجَةُ الَّتِيْ ثَبَّتَ اللهُ بِهَا قَلْبَهُ وَوَقَاهْ", "lt": "Wa awwalu man âmana bihî minar-rijâli abû bakrin shâḥibul-ghâri wash-shiddîqiyyah, wa minash-shibyâni ‘aliyy, wa minan-nisâ'i khadîjatul-latî tsabbatallâhu bihâ qalbahû wa waqâh", "id": "Orang pertama yang beriman kepada beliau dari kalangan laki-laki dewasa adalah Abu Bakar, sahabat di gua (Tsur) yang bergelar Ash-Shiddiq; dari kalangan anak-anak adalah Ali; dan dari kalangan wanita adalah Khadijah, yang dengannya Allah meneguhkan hati beliau dan melindunginya.", "no": 1},
{"ar": "وَمِنَ الْمَوَالِيْ زَيْدُ بْنُ حَارِثَةَ، وَمِنَ الْأَرِقَّاءِ بِلَالٌ الَّذِيْ عَذَّبَهُ فِي اللهِ أُمَيَّةْ، وَأَوْلَاهُ مَوْلَاهُ أَبُوْ بَكْرٍ مِنَ الْعِتْقِ مَا أَوْلَاهْ", "lt": "Wa minal-mawâlî zaidubnu ḥâritsah, wa minal-ariqqâ'i bilâlunil-ladzî ‘adzdzabahû fillâhi umayyah, wa aulâhu maulâhu abû bakrin minal-‘itqi mâ aulâh", "id": "Dari kalangan budak yang dimerdekakan adalah Zaid bin Haritsah, dan dari kalangan budak adalah Bilal yang disiksa oleh Umayyah karena (beriman kepada) Allah, lalu tuannya, Abu Bakar, memberinya kemerdekaan.", "no": 2},
{"ar": "ثُمَّ أَسْلَمَ عُثْمَانُ وَسَعْدٌ وَسَعِيْدٌ وَطَلْحَةُ وَابْنُ عَوْفٍ وَابْنُ عَمَّتِهِ صَفِيَّةْ، وَغَيْرُهُمْ مِمَّنْ أَنْهَلَهُ الصِّدِّيْقُ رَحِيْقَ التَّصْدِيْقِ وَسَقَاهْ", "lt": "Tsumma aslama ‘utsmânu wa sa‘dun wa sa‘îdun wa ṭalḥatu wabnu ‘aufin wabnu ‘ammatihî shafiyyah, wa ghairuhum mimman anhalahush-shiddîqu raḥîqat-tashdîqi wa saqâh", "id": "Kemudian masuk Islam Utsman, Sa‘ad, Sa‘id, Thalhah, Ibnu ‘Auf, putra bibinya Shafiyyah (Zubair), dan lainnya, yang diberi minum oleh Ash-Shiddiq dengan minuman pembenaran (iman).", "no": 3},
{"ar": "وَمَا زَالَتْ عِبَادَتُهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَصْحَابِهِ مَخْفِيَّةْ، حَتَّى أُنْزِلَتْ عَلَيْهِ (فَاصْدَعْ بِمَا تُؤْمَرُ) فَجَهَرَ بِدُعَاءِ الْخَلْقِ إِلَى اللهْ", "lt": "Wa mâ zâlat ‘ibâdatuhû shallallâhu ‘alaihi wa sallama wa ash-ḥâbihî makhfiyyah, ḥattâ unzilat ‘alaihi (fashda‘ bimâ tu'mar) fajahara bidu‘â'il-khalqi ilallâh", "id": "Ibadah beliau ﷺ dan para sahabatnya senantiasa dilakukan secara sembunyi-sembunyi, hingga turun kepadanya ayat (Fashda‘ bimâ tu'mar), maka beliau pun berdakwah mengajak manusia kepada Allah secara terang-terangan.", "no": 4},
{"ar": "وَلَمْ يَبْعُدْ مِنْهُ قَوْمُهُ حَتَّى عَابَ آلِهَتَهُمْ وَأَمَرَ بِرَفْضِ مَا سِوَى الْوَحْدَانِيَّةْ، فَتَجَرَّءُوْا عَلَى مُبَارَزَتِهِ بِالْعَدَاوَةِ وَأَذَاهْ", "lt": "Wa lam yab‘ud minhu qaumuhû ḥattâ ‘âba âlihatahum wa amara birafdli mâ siwal-waḥdâniyyah, fatajarra'û ‘alâ mubârazatihî bil-‘adâwati wa adzâh", "id": "Kaumnya tidak menjauhinya sampai beliau mencela sesembahan-sesembahan mereka dan memerintahkan untuk menolak selain tauhid. Maka mereka berani menantangnya dengan permusuhan dan menyakitinya.", "no": 5},
{"ar": "وَاشْتَدَّ عَلَى الْمُسْلِمِيْنَ الْبَلَاءُ فَهَاجَرُوْا فِيْ سَنَةِ خَمْسٍ إِلَى النَّاحِيَةِ النَّجَاشِيَّةْ، وَحَدِبَ عَلَيْهِ عَمُّهُ أَبُوْ طَالِبٍ فَهَابَهُ كُلٌّ مِنَ الْقَوْمِ وَتَحَامَاهْ", "lt": "Wasytadda ‘alal-muslimînal-balâ'u fahâjarû fî sanati khamsin ilan-nâḥiyatin-najâsyiyyah, wa ḥadiba ‘alaihi ‘ammuhû abû ṭâlibin fahâbahû kullun minal-qaumi wa taḥâmâh", "id": "Cobaan terhadap kaum muslimin semakin berat, maka pada tahun kelima mereka hijrah ke wilayah (kekuasaan) Najasyi. Pamannya, Abu Thalib, melindungi beliau dengan penuh kasih, sehingga semua orang segan dan menghindarinya.", "no": 6},
{"ar": "وَفُرِضَ عَلَيْهِ قِيَامُ بَعْضٍ مِنَ السَّاعَاتِ اللَّيْلِيَّةْ، ثُمَّ نُسِخَ بِقَوْلِهِ تَعَالَى (فَاقْرَءُوْا مَا تَيَسَّرَ مِنْهُ وَأَقِيْمُوا الصَّلَاةَ)", "lt": "Wa furidla ‘alaihi qiyâmu ba‘dlin minas-sâ‘âtil-lailiyyah, tsumma nusikha biqaulihî ta‘âlâ (faqra'û mâ tayassara minhu wa aqîmush-shalâh)", "id": "Diwajibkan atas beliau shalat malam pada sebagian waktu malam, kemudian kewajiban itu dihapus dengan firman-Nya Ta‘ala: (Maka bacalah apa yang mudah dari Al-Qur'an, dan dirikanlah shalat).", "no": 7},
{"ar": "وَفُرِضَ عَلَيْهِ رَكْعَتَانِ بِالْغَدَاةِ وَرَكْعَتَانِ بِالْعَشِيَّةْ، ثُمَّ نُسِخَ بِإِيْجَابِ الصَّلَوَاتِ الْخَمْسِ فِيْ لَيْلَةِ مَسْرَاهْ", "lt": "Wa furidla ‘alaihi rak‘atâni bil-ghadâti wa rak‘atâni bil-‘asyiyyah, tsumma nusikha bi'îjâbish-shalawâtil-khamsi fî lailati masrâh", "id": "Kemudian diwajibkan atasnya dua rakaat di pagi hari dan dua rakaat di sore hari, lalu dihapus dengan diwajibkannya shalat lima waktu pada malam Isra'.", "no": 8},
{"ar": "وَمَاتَ أَبُوْ طَالِبٍ فِيْ نِصْفِ شَوَّالٍ مِنْ عَاشِرِ الْبِعْثَةِ وَعَظُمَتْ بِمَوْتِهِ الرَّزِيَّةْ، وَتَلَتْهُ خَدِيْجَةُ بَعْدَ ثَلَاثٍ، وَشَدَّ الْبَلَاءُ عَلَى الْمُسْلِمِيْنَ عُرَاهْ", "lt": "Wa mâta abû ṭâlibin fî nishfi syawwâlin min ‘âsyiril-bi‘tsati wa ‘adhumat bimautihir-raziyyah, wa talat-hu khadîjatu ba‘da tsalâts, wa syaddal-balâ'u ‘alal-muslimîna ‘urâh", "id": "Abu Thalib wafat pada pertengahan bulan Syawal tahun kesepuluh kenabian, dan besarlah musibah karena kematiannya. Tiga hari kemudian Khadijah menyusulnya, dan cobaan terhadap kaum muslimin semakin mengikat erat.", "no": 9},
{"ar": "وَأَوْقَعَتْ قُرَيْشٌ بِهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّ أَذِيَّةْ، وَأَمَّ الطَّائِفَ يَدْعُوْ ثَقِيْفًا فَلَمْ يُحْسِنُوْا بِالْإِجَابَةِ قِرَاهْ", "lt": "Wa auqa‘at quraisyun bihî shallallâhu ‘alaihi wa sallama kulla adziyyah, wa ammaṭ-ṭâ'ifa yad‘û tsaqîfan falam yuḥsinû bil-ijâbati qirâh", "id": "Kaum Quraisy menimpakan segala macam gangguan kepada beliau ﷺ. Beliau pun pergi ke Thaif untuk mengajak kabilah Tsaqif, namun mereka tidak menyambutnya dengan baik.", "no": 10},
{"ar": "وَأَغْرَوْا بِهِ السُّفَهَاءَ وَالْعَبِيْدَ فَسَبُّوْهُ بِأَلْسِنَةٍ بَذِيَّةْ، وَرَمَوْهُ بِالْحِجَارَةِ حَتَّى خُضِبَتْ بِالدِّمَاءِ نَعْلَاهْ", "lt": "Wa aghrau bihis-sufahâ'a wal-‘abîda fasabbûhu bi'alsinatin badziyyah, wa ramauhu bil-ḥijârati ḥattâ khudlibat bid-dimâ'i na‘lâh", "id": "Mereka menghasut orang-orang bodoh dan para budak, yang lalu mencaci beliau dengan lisan yang kotor dan melemparinya dengan batu hingga kedua sandalnya berlumuran darah.", "no": 11},
{"ar": "ثُمَّ عَادَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى مَكَّةَ حَزِيْنًا، فَسَأَلَهُ مَلَكُ الْجِبَالِ فِيْ إِهْلَاكِ أَهْلِهَا ذَوِي الْعَصَبِيَّةْ، فَقَالَ: إِنِّيْ أَرْجُوْ أَنْ يُخْرِجَ اللهُ تَعَالَى مِنْ أَصْلَابِهِمْ مَنْ يَتَوَلَّاهْ", "lt": "Tsumma ‘âda shallallâhu ‘alaihi wa sallama ilâ makkata ḥazînâ, fasa'alahû malakul-jibâli fî ihlâki ahlihâ dzawil-‘ashabiyyah, faqâla: innî arjû an yukhrijallâhu ta‘âlâ min ashlâbihim man yatawallâh", "id": "Kemudian beliau ﷺ kembali ke Makkah dengan sedih. Malaikat penjaga gunung meminta izin kepada beliau untuk membinasakan penduduknya yang fanatik itu, namun beliau bersabda: Sesungguhnya aku berharap Allah Ta‘ala akan mengeluarkan dari sulbi-sulbi mereka orang yang menyembah-Nya.", "no": 12},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 13}]},
{judul:"Isra' Mi'raj",isi:[
{"ar": "ثُمَّ أُسْرِيَ بِرُوْحِهِ وَجَسَدِهِ يَقَظَةً مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى وَرِحَابِهِ الْقُدْسِيَّةْ، وَعُرِجَ بِهِ إِلَى السَّمٰوَاتِ فَرَأَى آدَمَ فِي الْأُوْلَى وَقَدْ جَلَّلَهُ الْوَقَارُ وَعَلَاهْ", "lt": "Tsumma usriya birûḥihî wa jasadihî yaqadhatan minal-masjidil-ḥarâmi ilal-masjidil-aqshâ wa riḥâbihil-qudsiyyah, wa ‘urija bihî ilas-samâwâti fara'â âdama fil-ûlâ wa qad jallalahul-waqâru wa ‘alâh", "id": "Kemudian beliau diperjalankan dengan ruh dan jasadnya dalam keadaan terjaga dari Masjidil Haram ke Masjidil Aqsha dan pelatarannya yang suci. Lalu beliau dinaikkan ke langit; di langit pertama beliau melihat Adam yang diliputi dan dinaungi kewibawaan.", "no": 1},
{"ar": "وَرَأَى فِي الثَّانِيَةِ عِيْسَى ابْنَ مَرْيَمَ الْبَتُوْلِ الْبَرَّةِ التَّقِيَّةْ، وَابْنَ خَالَتِهِ يَحْيَى الَّذِيْ أُوْتِيَ الْحُكْمَ فِيْ حَالِ صِبَاهْ", "lt": "Wa ra'â fits-tsâniyati ‘îsabna maryamal-batûlil-barratit-taqiyyah, wabna khâlatihî yaḥyal-ladzî ûtiyal-ḥukma fî ḥâli shibâh", "id": "Di langit kedua beliau melihat Isa putra Maryam, wanita suci yang baik lagi bertakwa, dan putra bibinya, Yahya, yang diberi hikmah sejak masih kanak-kanak.", "no": 2},
{"ar": "وَرَأَى فِي الثَّالِثَةِ يُوْسُفَ الصِّدِّيْقَ بِصُوْرَتِهِ الْجَمَالِيَّةْ، وَفِي الرَّابِعَةِ إِدْرِيْسَ الَّذِيْ رَفَعَ اللهُ مَكَانَهُ وَأَعْلَاهْ", "lt": "Wa ra'â fits-tsâlitsati yûsufash-shiddîqa bishûratihil-jamâliyyah, wa fir-râbi‘ati idrîsal-ladzî rafa‘allâhu makânahû wa a‘lâh", "id": "Di langit ketiga beliau melihat Yusuf yang benar dengan rupanya yang tampan; di langit keempat Idris, yang Allah angkat dan tinggikan kedudukannya.", "no": 3},
{"ar": "وَفِي الْخَامِسَةِ هَارُوْنَ الْمُحَبَّبَ فِي الْأُمَّةِ الْإِسْرَائِيْلِيَّةْ، وَفِي السَّادِسَةِ مُوْسَى الَّذِيْ كَلَّمَهُ اللهُ تَعَالَى وَنَاجَاهْ", "lt": "Wa fil-khâmisati hârûnal-muḥabbaba fil-ummatil-isrâ'îliyyah, wa fis-sâdisati mûsal-ladzî kallamahullâhu ta‘âlâ wa nâjâh", "id": "Di langit kelima Harun yang dicintai di kalangan Bani Israil; di langit keenam Musa, yang Allah Ta‘ala ajak bicara dan bermunajat dengan-Nya.", "no": 4},
{"ar": "وَفِي السَّابِعَةِ إِبْرَاهِيْمَ الَّذِيْ جَاءَ رَبَّهُ بِسَلَامَةِ الْقَلْبِ وَالطَّوِيَّةْ، وَحَفِظَهُ اللهُ مِنْ نَارِ النَّمْرُوْدِ وَعَافَاهْ", "lt": "Wa fis-sâbi‘ati ibrâhîmal-ladzî jâ'a rabbahû bisalâmatil-qalbi waṭ-ṭawiyyah, wa ḥafidhahullâhu min nârin-namrûdi wa ‘âfâh", "id": "Di langit ketujuh Ibrahim, yang datang kepada Tuhannya dengan hati dan batin yang selamat, dan yang Allah jaga serta selamatkan dari api Namrud.", "no": 5},
{"ar": "ثُمَّ رُفِعَ إِلَى سِدْرَةِ الْمُنْتَهَى إِلَى أَنْ سَمِعَ صَرِيْفَ الْأَقْلَامِ بِالْأُمُوْرِ الْمَقْضِيَّةْ، إِلَى مَقَامِ الْمُكَافَحَةِ الَّذِيْ قَرَّبَهُ اللهُ فِيْهِ وَأَدْنَاهْ", "lt": "Tsumma rufi‘a ilâ sidratil-muntahâ ilâ an sami‘a sharîfal-aqlâmi bil-umûril-maqdliyyah, ilâ maqâmil-mukâfaḥatil-ladzî qarrabahullâhu fîhi wa adnâh", "id": "Kemudian beliau diangkat ke Sidratul Muntaha hingga mendengar goresan pena-pena (yang menulis) segala ketetapan, sampai ke tempat berhadapan langsung, di mana Allah mendekatkan dan mendekatkannya lagi.", "no": 6},
{"ar": "وَأَمَاطَ لَهُ حُجُبَ الْأَنْوَارِ الْجَلَالِيَّةْ، وَأَرَاهُ بِعَيْنَيْ رَأْسِهِ مِنْ حَضْرَةِ الرُّبُوْبِيَّةِ مَا أَرَاهْ", "lt": "Wa amâṭa lahû ḥujubal-anwâril-jalâliyyah, wa arâhu bi‘ainai ra'sihî min ḥadlratir-rubûbiyyati mâ arâh", "id": "Allah menyingkapkan baginya tirai-tirai cahaya keagungan, dan memperlihatkan kepadanya dengan kedua mata kepalanya apa yang Dia perlihatkan dari hadirat ketuhanan.", "no": 7},
{"ar": "وَبَسَطَ لَهُ بُسُطَ الْإِدْلَالِ فِي الْمَجَالِي الذَّاتِيَّةْ، وَفَرَضَ عَلَيْهِ وَعَلَى أُمَّتِهِ خَمْسِيْنَ صَلَاهْ", "lt": "Wa basaṭa lahû busuṭal-idlâli fil-majâlidz-dzâtiyyah, wa faradla ‘alaihi wa ‘alâ ummatihî khamsîna shalâh", "id": "Allah membentangkan baginya hamparan kemesraan di tempat-tempat penampakan Dzat-Nya, dan mewajibkan atas beliau dan umatnya lima puluh kali shalat.", "no": 8},
{"ar": "ثُمَّ انْهَلَّ سَحَابُ الْفَضْلِ فَرُدَّتْ إِلَى خَمْسٍ عَمَلِيَّةْ، وَلَهَا أَجْرُ الْخَمْسِيْنَ كَمَا شَاءَهُ فِي الْأَزَلِ وَقَضَاهْ", "lt": "Tsumman-hallâ saḥâbul-fadlli faruddat ilâ khamsin ‘amaliyyah, wa lahâ ajrul-khamsîna kamâ syâ'ahû fil-azali wa qadlâh", "id": "Kemudian awan karunia mencurahkan hujannya, sehingga kewajiban itu dikembalikan menjadi lima (shalat) dalam pelaksanaan, namun pahalanya tetap lima puluh, sebagaimana yang Allah kehendaki dan tetapkan sejak azali.", "no": 9},
{"ar": "ثُمَّ عَادَ فِيْ لَيْلَتِهِ بِالْمَوَاهِبِ اللَّدُنِّيَّةْ، فَصَدَّقَهُ الصِّدِّيْقُ بِمَسْرَاهُ وَكُلُّ ذِيْ عَقْلٍ وَرَوِيَّةْ، وَكَذَّبَتْهُ قُرَيْشٌ وَارْتَدَّ مَنْ أَضَلَّهُ الشَّيْطَانُ وَأَغْوَاهْ", "lt": "Tsumma ‘âda fî lailatihî bil-mawâhibil-ladunniyyah, fashaddaqahush-shiddîqu bimasrâhu wa kullu dzî ‘aqlin wa rawiyyah, wa kadzdzabat-hu quraisyun wartadda man adlallahusy-syaiṭânu wa aghwâh", "id": "Kemudian beliau kembali pada malam itu juga dengan membawa anugerah-anugerah dari sisi Allah. Ash-Shiddiq membenarkan perjalanan malamnya, demikian pula setiap orang yang berakal dan berpikir, sedangkan Quraisy mendustakannya, dan murtadlah orang yang disesatkan dan diperdaya setan.", "no": 10},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 11}]},
{judul:"Bai'at Kaum Anshar dan Hijrah",isi:[
{"ar": "ثُمَّ عَرَضَ نَفْسَهُ عَلَى الْقَبَائِلِ بِأَنَّهُ رَسُوْلُ اللهِ فِي الْأَيَّامِ الْمَوْسِمِيَّةْ، فَآمَنَ بِهِ سِتَّةٌ مِنَ الْأَنْصَارِ اخْتَصَّهُمُ اللهُ تَعَالَى بِرِضَاهْ", "lt": "Tsumma ‘aradla nafsahû ‘alal-qabâ'ili bi'annahû rasûlullâhi fil-ayyâmil-mausimiyyah, fa âmana bihî sittatun minal-anshârikh-tashshahumullâhu ta‘âlâ biridlâh", "id": "Kemudian pada musim-musim haji beliau menawarkan diri kepada kabilah-kabilah bahwa beliau adalah utusan Allah. Maka berimanlah kepadanya enam orang dari kaum Anshar yang Allah Ta‘ala istimewakan dengan keridaan-Nya.", "no": 1},
{"ar": "وَحَجَّ مِنْهُمْ فِي الْقَابِلِ اثْنَا عَشَرَ رَجُلًا وَبَايَعُوْهُ بَيْعَةً حَفِيَّةْ، ثُمَّ انْصَرَفُوْا وَظَهَرَ الْإِسْلَامُ بِالْمَدِيْنَةِ فَكَانَتْ مَعْقِلَهُ وَمَأْوَاهْ", "lt": "Wa ḥajja minhum fil-qâbilitsnâ ‘asyara rajulan wa bâya‘ûhu bai‘atan ḥafiyyah, tsumman-sharafû wa dhaharal-islâmu bil-madînati fakânat ma‘qilahû wa ma'wâh", "id": "Pada tahun berikutnya, dua belas orang dari mereka berhaji dan berbaiat kepada beliau dengan baiat yang penuh kesungguhan. Kemudian mereka pulang, dan Islam pun tampak di Madinah, sehingga kota itu menjadi benteng dan tempat berlindungnya.", "no": 2},
{"ar": "وَقَدِمَ عَلَيْهِ فِي الثَّالِثَةِ سَبْعُوْنَ أَوْ خَمْسَةٌ أَوْ ثَلَاثَةٌ وَامْرَأَتَانِ مِنَ الْقَبَائِلِ الْأَوْسِيَّةِ وَالْخَزْرَجِيَّةْ، فَبَايَعُوْهُ وَأَمَّرَ عَلَيْهِمُ اثْنَيْ عَشَرَ نَقِيْبًا جَحَاجِحَةً سَرَاهْ", "lt": "Wa qadima ‘alaihi fits-tsâlitsati sab‘ûna au khamsatun au tsalâtsatun wamra'atâni minal-qabâ'ilil-ausiyyati wal-khazrajiyyah, fabâya‘ûhu wa ammara ‘alaihimutsnai ‘asyara naqîban jaḥâjiḥatan sarâh", "id": "Pada tahun ketiga datang kepada beliau tujuh puluh (atau tujuh puluh lima, atau tujuh puluh tiga) laki-laki dan dua orang wanita dari kabilah Aus dan Khazraj. Mereka berbaiat kepada beliau, dan beliau mengangkat dua belas orang pemimpin yang mulia lagi terhormat atas mereka.", "no": 3},
{"ar": "وَهَاجَرَ إِلَيْهِمْ مِنْ مَكَّةَ ذَوُو الْمِلَّةِ الْإِسْلَامِيَّةْ، وَفَارَقُوا الْأَوْطَانَ رَغْبَةً فِيْمَا أُعِدَّ لِمَنْ هَجَرَ الْكُفْرَ وَنَاوَاهْ", "lt": "Wa hâjara ilaihim min makkata dzawul-millatil-islâmiyyah, wa fâraqul-auṭâna raghbatan fîmâ u‘idda liman hajaral-kufra wa nâwâh", "id": "Para pemeluk agama Islam dari Makkah berhijrah kepada mereka, meninggalkan tanah air karena mengharapkan (pahala) yang disediakan bagi orang yang meninggalkan dan memusuhi kekafiran.", "no": 4},
{"ar": "وَخَافَتْ قُرَيْشٌ أَنْ يَلْحَقَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِأَصْحَابِهِ عَلَى الْفَوْرِيَّةْ، فَأْتَمَرُوْا بِقَتْلِهِ فَحَفِظَهُ اللهُ تَعَالَى مِنْ كَيْدِهِمْ وَنَجَّاهْ", "lt": "Wa khâfat quraisyun an yalḥaqa shallallâhu ‘alaihi wa sallama bi'ash-ḥâbihî ‘alal-fauriyyah, fa'tamarû biqatlihî faḥafidhahullâhu ta‘âlâ min kaidihim wa najjâh", "id": "Kaum Quraisy khawatir beliau ﷺ segera menyusul para sahabatnya, maka mereka bersekongkol untuk membunuhnya. Namun Allah Ta‘ala menjaganya dari tipu daya mereka dan menyelamatkannya.", "no": 5},
{"ar": "وَأُذِنَ لَهُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الْهِجْرَةِ، فَرَقَبَهُ الْمُشْرِكُوْنَ لِيُوْرِدُوْهُ بِزَعْمِهِمْ حِيَاضَ الْمَنِيَّةْ، فَخَرَجَ عَلَيْهِمْ وَنَثَرَ عَلَى رُءُوْسِهِمُ التُّرَابَ وَحَثَاهْ", "lt": "Wa udzina lahû shallallâhu ‘alaihi wa sallama fil-hijrah, faraqabahul-musyrikûna liyûridûhu biza‘mihim ḥiyâdlal-maniyyah, fakharaja ‘alaihim wa natsara ‘alâ ru'ûsihimut-turâba wa ḥatsâh", "id": "Beliau ﷺ diizinkan untuk berhijrah. Kaum musyrikin mengintainya untuk, menurut sangkaan mereka, mengantarkannya ke kolam kematian. Namun beliau keluar melewati mereka dan menaburkan debu di atas kepala mereka.", "no": 6},
{"ar": "وَأَمَّ غَارَ ثَوْرٍ وَفَازَ الصِّدِّيْقُ بِالْمَعِيَّةْ، وَأَقَامَا فِيْهِ ثَلَاثًا تَحْمِي الْحَمَائِمُ وَالْعَنَاكِبُ حِمَاهْ", "lt": "Wa amma ghâra tsaurin wa fâzash-shiddîqu bil-ma‘iyyah, wa aqâmâ fîhi tsalâtsan taḥmil-ḥamâ'imu wal-‘anâkibu ḥimâh", "id": "Beliau menuju Gua Tsur, dan Ash-Shiddiq beruntung dapat menyertainya. Keduanya tinggal di sana selama tiga hari, sementara burung-burung merpati dan laba-laba melindungi tempat itu.", "no": 7},
{"ar": "ثُمَّ خَرَجَا مِنْهُ لَيْلَةَ الْاِثْنَيْنِ وَهُوَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى خَيْرِ مَطِيَّةْ، وَتَعَرَّضَ لَهُ سُرَاقَةُ فَابْتَهَلَ فِيْهِ إِلَى اللهِ تَعَالَى وَدَعَاهْ", "lt": "Tsumma kharajâ minhu lailatal-itsnaini wa huwa shallallâhu ‘alaihi wa sallama ‘alâ khairi maṭiyyah, wa ta‘arradla lahû surâqatu fabtahala fîhi ilallâhi ta‘âlâ wa da‘âh", "id": "Kemudian keduanya keluar dari gua itu pada malam Senin, beliau ﷺ menunggangi kendaraan terbaik. Suraqah menghadang beliau, maka beliau memohon dan berdoa kepada Allah Ta‘ala tentangnya.", "no": 8},
{"ar": "فَسَاخَتْ قَوَائِمُ يَعْبُوْبِهِ فِي الْأَرْضِ الصُّلْبَةِ الْقَوِيَّةْ، وَسَأَلَهُ الْأَمَانَ فَمَنَحَهُ إِيَّاهْ", "lt": "Fasâkhat qawâ'imu ya‘bûbihî fil-ardlish-shulbatil-qawiyyah, wa sa'alahul-amâna famanaḥahû iyyâh", "id": "Maka kaki-kaki kudanya yang tangkas terbenam ke dalam tanah yang keras lagi kokoh. Suraqah pun meminta jaminan keamanan kepada beliau, dan beliau memberikannya.", "no": 9},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 10}]},
{judul:"Ummu Ma'bad dan Tiba di Madinah",isi:[
{"ar": "وَمَرَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِقُدَيْدٍ عَلَى أُمِّ مَعْبَدٍ الْخُزَاعِيَّةْ، وَأَرَادَ ابْتِيَاعَ لَبَنٍ أَوْ لَحْمٍ مِنْهَا فَلَمْ يَكُنْ لِشَيْءٍ مِنْ ذٰلِكَ خِبَاؤُهَا قَدْ حَوَاهْ", "lt": "Wa marra shallallâhu ‘alaihi wa sallama biqudaidin ‘alâ ummi ma‘badinil-khuzâ‘iyyah, wa arâdab-tiyâ‘a labanin au laḥmin minhâ falam yakun lisyai'in min dzâlika khibâ'uhâ qad ḥawâh", "id": "Beliau ﷺ melewati Qudaid dan singgah di tempat Ummu Ma‘bad dari Bani Khuza‘ah. Beliau hendak membeli susu atau daging darinya, namun kemahnya tidak memiliki apa pun dari itu.", "no": 1},
{"ar": "فَنَظَرَ إِلَى شَاةٍ فِي الْبَيْتِ قَدْ خَلَّفَهَا الْجَهْدُ عَنِ الرَّعِيَّةْ، فَاسْتَأْذَنَهَا فِيْ حَلْبِهَا فَأَذِنَتْ، وَقَالَتْ: لَوْ كَانَ بِهَا حَلَبٌ لَأَصَبْنَاهْ", "lt": "Fanadhara ilâ syâtin fil-baiti qad khallafahal-jahdu ‘anir-ra‘iyyah, fasta'dzanahâ fî ḥalbihâ fa adzinat, wa qâlat: lau kâna bihâ ḥalabun la'ashabnâh", "id": "Beliau melihat seekor kambing di dalam kemah yang tertinggal dari kawanannya karena lemah. Beliau meminta izin untuk memerahnya, dan Ummu Ma‘bad mengizinkan sambil berkata: Kalau kambing itu ada susunya, tentu sudah kami perah.", "no": 2},
{"ar": "فَمَسَحَ ضَرْعَهَا مِنْهَا وَدَعَا اللهَ مَوْلَاهُ وَوَلِيَّهْ، فَدَرَّتْ فَحَلَبَ وَسَقَى كُلًّا مِنَ الْقَوْمِ وَأَرْوَاهْ", "lt": "Famasaḥa dlar‘ahâ minhâ wa da‘allâha maulâhu wa waliyyah, fadarrat faḥalaba wa saqâ kullan minal-qaumi wa arwâh", "id": "Beliau mengusap ambingnya dan berdoa kepada Allah, Tuhan dan Pelindungnya. Maka mengalirlah susunya; beliau memerahnya dan memberi minum setiap orang dalam rombongan hingga puas.", "no": 3},
{"ar": "ثُمَّ حَلَبَ وَمَلَأَ الْإِنَاءَ وَغَادَرَهُ لَدَيْهَا آيَةً جَلِيَّةْ، وَجَاءَ أَبُوْ مَعْبَدٍ وَرَأَى اللَّبَنَ فَذَهَبَ بِهِ الْعَجَبُ إِلَى أَقْصَاهْ", "lt": "Tsumma ḥalaba wa mala'al-inâ'a wa ghâdarahû ladaihâ âyatan jaliyyah, wa jâ'a abû ma‘badin wa ra'al-labana fadzahaba bihil-‘ajabu ilâ aqshâh", "id": "Kemudian beliau memerah lagi hingga memenuhi bejana dan meninggalkannya di sisinya sebagai tanda yang nyata. Abu Ma‘bad pun datang dan melihat susu itu, maka ia sangat takjub.", "no": 4},
{"ar": "وَقَالَ: أَنَّى لَكِ هٰذَا وَلَا حَلُوْبَ بِالْبَيْتِ تَبِضُّ بِقَطْرَةٍ لَبَنِيَّةْ، فَقَالَتْ: مَرَّ بِنَا رَجُلٌ مُبَارَكٌ كَذَا وَكَذَا جُثْمَانُهُ وَمَعْنَاهْ", "lt": "Wa qâla: annâ laki hâdzâ wa lâ ḥalûba bil-baiti tabidldlu biqaṭratin labaniyyah, faqâlat: marra binâ rajulun mubârakun kadzâ wa kadzâ jutsmânuhû wa ma‘nâh", "id": "Ia berkata: Dari mana engkau mendapatkan ini, padahal tidak ada hewan perahan di rumah yang dapat meneteskan setetes susu pun? Ummu Ma‘bad menjawab: Seorang laki-laki yang penuh berkah melewati kami, begini dan begini sosok dan sifatnya.", "no": 5},
{"ar": "فَقَالَ لَهَا: هٰذَا صَاحِبُ قُرَيْشٍ، وَأَقْسَمَ بِكُلِّ أَلِيَّةْ، عَلَى أَنَّهُ لَوْ رَآهُ لَآمَنَ بِهِ وَاتَّبَعَهُ وَدَانَاهْ", "lt": "Faqâla lahâ: hâdzâ shâḥibu quraisy, wa aqsama bikulli aliyyah, ‘alâ annahû lau ra'âhu la'âmana bihî wattaba‘ahû wa dânâh", "id": "Abu Ma‘bad berkata kepadanya: Itulah laki-laki Quraisy (yang dibicarakan orang). Lalu ia bersumpah dengan segala sumpah, bahwa seandainya ia melihatnya, pasti ia akan beriman kepadanya, mengikutinya, dan mendekat kepadanya.", "no": 6},
{"ar": "وَقَدِمَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَدِيْنَةَ يَوْمَ الْاِثْنَيْنِ ثَانِيَ عَشَرَ رَبِيْعٍ الْأَوَّلِ وَأَشْرَقَتْ بِهِ أَرْجَاؤُهَا الزَّكِيَّةْ، وَتَلَقَّاهُ الْأَنْصَارُ وَنَزَلَ بِقُبَاءَ وَأَسَّسَ مَسْجِدَهَا عَلَى تَقْوَاهْ", "lt": "Wa qadima shallallâhu ‘alaihi wa sallamal-madînata yaumal-itsnaini tsâniya ‘asyara rabî‘il-awwali wa asyraqat bihî arjâ'uhaz-zakiyyah, wa talaqqâhul-anshâru wa nazala biqubâ'a wa assasa masjidahâ ‘alâ taqwâh", "id": "Beliau ﷺ tiba di Madinah pada hari Senin tanggal dua belas Rabiul Awal, dan seluruh penjurunya yang suci bersinar karena kedatangannya. Kaum Anshar menyambutnya, dan beliau singgah di Quba serta mendirikan masjidnya atas dasar takwa.", "no": 7},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 8}]},
{judul:"Sifat dan Akhlak Nabi",isi:[
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَكْمَلَ النَّاسِ خَلْقًا وَخُلُقًا، ذَا ذَاتٍ وَصِفَاتٍ سَنِيَّةْ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama akmalan-nâsi khalqan wa khuluqâ, dzâ dzâtin wa shifâtin saniyyah", "id": "Beliau ﷺ adalah manusia yang paling sempurna rupa dan akhlaknya, memiliki pribadi dan sifat-sifat yang luhur.", "no": 1},
{"ar": "مَرْبُوْعَ الْقَامَةِ، أَبْيَضَ اللَّوْنِ مُشْرَبًا بِحُمْرَةٍ، وَاسِعَ الْعَيْنَيْنِ أَكْحَلَهُمَا أَهْدَبَ الْأَشْفَارِ، قَدْ مُنِحَ الزَّجَجَ حَاجِبَاهْ", "lt": "Marbû‘al-qâmah, abyadlal-launi musyraban biḥumrah, wâsi‘al-‘ainaini akḥalahumâ ahdabal-asyfâr, qad muniḥaz-zajaja ḥâjibâh", "id": "Tingginya sedang, kulitnya putih kemerah-merahan, kedua matanya lebar dan hitam seperti bercelak, bulu matanya lentik, dan kedua alisnya melengkung tipis memanjang.", "no": 2},
{"ar": "مُفَلَّجَ الْأَسْنَانِ، وَاسِعَ الْفَمِ حَسَنَهُ، وَاسِعَ الْجَبِيْنِ ذَا جَبْهَةٍ هِلَالِيَّةْ، سَهْلَ الْخَدَّيْنِ يُرَى فِيْ أَنْفِهِ بَعْضُ احْدِيْدَابٍ حَسَنَ الْعِرْنِيْنِ أَقْنَاهْ", "lt": "Mufallajal-asnân, wâsi‘al-fami ḥasanah, wâsi‘al-jabîni dzâ jabhatin hilâliyyah, sahlal-khaddaini yurâ fî anfihî ba‘dluḥ-dîdâbin ḥasanal-‘irnîni aqnâh", "id": "Giginya renggang (indah), mulutnya lebar dan bagus, dahinya lebar bagaikan bulan sabit, kedua pipinya halus, hidungnya sedikit melengkung, dan batang hidungnya indah lagi mancung.", "no": 3},
{"ar": "بَعِيْدَ مَا بَيْنَ الْمَنْكِبَيْنِ، سَبْطَ الْكَفَّيْنِ، ضَخْمَ الْكَرَادِيْسِ، قَلِيْلَ لَحْمِ الْعَقِبِ، كَثَّ اللِّحْيَةِ، عَظِيْمَ الرَّأْسِ، شَعْرُهُ إِلَى الشَّحْمَةِ الْأُذُنِيَّةْ", "lt": "Ba‘îda mâ bainal-mankibain, sabṭal-kaffain, dlakhmal-karâdîs, qalîla laḥmil-‘aqib, katstsal-liḥyah, ‘adhîmar-ra's, sya‘ruhû ilasy-syaḥmatil-udzuniyyah", "id": "Jarak antara kedua bahunya lebar, kedua telapak tangannya lembut, persendian tulangnya besar, sedikit daging tumitnya, janggutnya lebat, kepalanya besar, dan rambutnya sampai ke cuping telinga.", "no": 4},
{"ar": "وَبَيْنَ كَتِفَيْهِ خَاتَمُ النُّبُوَّةِ قَدْ عَمَّهُ النُّوْرُ وَعَلَاهْ، وَعَرَقُهُ كَاللُّؤْلُؤِ وَعَرْفُهُ أَطْيَبُ مِنَ النَّفَحَاتِ الْمِسْكِيَّةْ", "lt": "Wa baina katifaihi khâtamun-nubuwwati qad ‘ammahun-nûru wa ‘alâh, wa ‘araquhû kal-lu'lu'i wa ‘arfuhû aṭyabu minan-nafaḥâtil-miskiyyah", "id": "Di antara kedua bahunya ada cap kenabian yang diliputi dan dinaungi cahaya. Keringatnya bagaikan mutiara, dan aromanya lebih harum daripada embusan wangi kesturi.", "no": 5},
{"ar": "وَيَتَكَفَّأُ فِيْ مِشْيَتِهِ كَأَنَّمَا يَنْحَطُّ مِنْ صَبَبٍ ارْتَقَاهْ", "lt": "Wa yatakaffa'u fî misyyatihî ka'annamâ yanḥaṭṭu min shababinir-taqâh", "id": "Ketika berjalan, langkahnya condong ke depan seakan-akan sedang turun dari tempat yang tinggi.", "no": 6},
{"ar": "وَكَانَ يُصَافِحُ الْمُصَافِحَ بِيَدِهِ الشَّرِيْفَةِ فَيَجِدُ مِنْهَا سَائِرَ الْيَوْمِ رَائِحَةً عَبْهَرِيَّةْ، وَيَضَعُهَا عَلَى رَأْسِ الصَّبِيِّ فَيُعْرَفُ مَسُّهُ لَهُ مِنْ بَيْنِ الصِّبْيَةِ وَيُدْرَاهْ", "lt": "Wa kâna yushâfiḥul-mushâfiḥa biyadihisy-syarîfati fayajidu minhâ sâ'iral-yaumi râ'iḥatan ‘abhariyyah, wa yadla‘uhâ ‘alâ ra'sish-shabiyyi fayu‘rafu massuhû lahû min bainish-shibyati wa yudrâh", "id": "Bila beliau berjabat tangan dengan seseorang dengan tangannya yang mulia, orang itu mencium bau harum sepanjang hari. Bila beliau meletakkan tangannya di atas kepala seorang anak, anak itu dikenal di antara anak-anak lain karena sentuhan beliau.", "no": 7},
{"ar": "يَتَلَأْلَأُ وَجْهُهُ الشَّرِيْفُ تَلَأْلُؤَ الْقَمَرِ فِي اللَّيْلَةِ الْبَدْرِيَّةْ، يَقُوْلُ نَاعِتُهُ: لَمْ أَرَ قَبْلَهُ وَلَا بَعْدَهُ مِثْلَهُ وَلَا بَشَرٌ يَرَاهْ", "lt": "Yatala'la'u wajhuhusy-syarîfu tala'lu'al-qamari fil-lailatil-badriyyah, yaqûlu nâ‘ituhû: lam ara qablahû wa lâ ba‘dahû mitslahû wa lâ basyarun yarâh", "id": "Wajahnya yang mulia berkilau bagaikan bulan di malam purnama. Orang yang menyifatinya berkata: Aku tidak pernah melihat seorang pun seperti beliau, sebelum maupun sesudahnya, dan tidak ada manusia yang (pernah) melihat (yang serupa) dengannya.", "no": 8},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 9}]},
{judul:"Kerendahan Hati Nabi",isi:[
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ شَدِيْدَ الْحَيَاءِ وَالتَّوَاضُعِ، يَخْصِفُ نَعْلَهُ وَيَرْقَعُ ثَوْبَهُ وَيَحْلُبُ شَاتَهُ، وَيَسِيْرُ فِيْ خِدْمَةِ أَهْلِهِ بِسِيْرَةٍ سَرِيَّةْ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama syadîdal-ḥayâ'i wat-tawâdlu‘, yakhshifu na‘lahû wa yarqa‘u tsaubahû wa yaḥlubu syâtah, wa yasîru fî khidmati ahlihî bisîratin sariyyah", "id": "Beliau ﷺ sangat pemalu dan rendah hati. Beliau menjahit sandalnya sendiri, menambal bajunya, memerah susu kambingnya, dan melayani keluarganya dengan perilaku yang mulia.", "no": 1},
{"ar": "وَيُحِبُّ الْفُقَرَاءَ وَالْمَسَاكِيْنَ وَيَجْلِسُ مَعَهُمْ، وَيَعُوْدُ مَرْضَاهُمْ وَيُشَيِّعُ جَنَائِزَهُمْ، وَلَا يَحْقِرُ فَقِيْرًا أَدْقَعَهُ الْفَقْرُ وَأَشْوَاهْ", "lt": "Wa yuḥibbul-fuqarâ'a wal-masâkîna wa yajlisu ma‘ahum, wa ya‘ûdu mardlâhum wa yusyayyi‘u janâ'izahum, wa lâ yaḥqiru faqîran adqa‘ahul-faqru wa asywâh", "id": "Beliau mencintai orang-orang fakir dan miskin, duduk bersama mereka, menjenguk yang sakit di antara mereka, mengantarkan jenazah mereka, dan tidak meremehkan orang fakir yang dihinakan dan dilemahkan oleh kefakirannya.", "no": 2},
{"ar": "وَيَقْبَلُ الْمَعْذِرَةَ وَلَا يُقَابِلُ أَحَدًا بِمَا يَكْرَهُ، وَيَمْشِيْ مَعَ الْأَرْمَلَةِ وَذَوِي الْعُبُوْدِيَّةْ", "lt": "Wa yaqbalul-ma‘dzirata wa lâ yuqâbilu aḥadan bimâ yakrah, wa yamsyî ma‘al-armalati wa dzawil-‘ubûdiyyah", "id": "Beliau menerima permintaan maaf, tidak menghadapi seseorang dengan sesuatu yang tidak disukainya, dan berjalan bersama janda serta para budak (untuk membantu keperluan mereka).", "no": 3},
{"ar": "وَلَا يَهَابُ الْمُلُوْكَ، وَيَغْضَبُ لِلّٰهِ تَعَالَى وَيَرْضَى لِرِضَاهْ", "lt": "Wa lâ yahâbul-mulûk, wa yaghdlabu lillâhi ta‘âlâ wa yardlâ liridlâh", "id": "Beliau tidak gentar kepada para raja; beliau marah karena Allah Ta‘ala dan rida karena keridaan-Nya.", "no": 4},
{"ar": "وَيَمْشِيْ خَلْفَ أَصْحَابِهِ وَيَقُوْلُ: خَلُّوْا ظَهْرِيْ لِلْمَلَائِكَةِ الرُّوْحَانِيَّةْ، وَيَرْكَبُ الْبَعِيْرَ وَالْفَرَسَ وَالْبَغْلَةَ وَحِمَارًا بَعْضُ الْمُلُوْكِ إِلَيْهِ أَهْدَاهْ", "lt": "Wa yamsyî khalfa ash-ḥâbihî wa yaqûlu: khallû dhahrî lil-malâ'ikatir-rûḥâniyyah, wa yarkabul-ba‘îra wal-farasa wal-baghlata wa ḥimâran ba‘dlul-mulûki ilaihi ahdâh", "id": "Beliau berjalan di belakang para sahabatnya dan bersabda: Biarkan punggungku untuk para malaikat. Beliau menunggangi unta, kuda, bighal, dan keledai yang dihadiahkan oleh sebagian raja kepadanya.", "no": 5},
{"ar": "وَيَعْصِبُ عَلَى بَطْنِهِ الْحَجَرَ مِنَ الْجُوْعِ وَقَدْ أُوْتِيَ مَفَاتِيْحَ الْخَزَائِنِ الْأَرْضِيَّةْ، وَرَاوَدَتْهُ الْجِبَالُ بِأَنْ تَكُوْنَ لَهُ ذَهَبًا فَأَبَاهْ", "lt": "Wa ya‘shibu ‘alâ baṭnihil-ḥajara minal-jû‘i wa qad ûtiya mafâtîḥal-khazâ'inil-ardliyyah, wa râwadat-hul-jibâlu bi'an takûna lahû dzahaban fa abâh", "id": "Beliau mengikatkan batu di perutnya karena lapar, padahal beliau telah diberi kunci-kunci perbendaharaan bumi. Gunung-gunung menawarkan diri untuk menjadi emas baginya, namun beliau menolaknya.", "no": 6},
{"ar": "وَكَانَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُقِلُّ اللَّغْوَ، وَيَبْدَأُ مَنْ لَقِيَهُ بِالسَّلَامِ، وَيُطِيْلُ الصَّلَاةَ، وَيَقْصُرُ الْخُطَبَ الْجُمُعِيَّةْ", "lt": "Wa kâna shallallâhu ‘alaihi wa sallama yuqillul-laghw, wa yabda'u man laqiyahû bis-salâm, wa yuṭîlush-shalâh, wa yaqshurul-khuṭabal-jumu‘iyyah", "id": "Beliau ﷺ sedikit berbicara yang sia-sia, mendahului memberi salam kepada orang yang ditemuinya, memanjangkan shalat, dan memendekkan khutbah Jumat.", "no": 7},
{"ar": "وَيَتَأَلَّفُ أَهْلَ الشَّرَفِ وَيُكْرِمُ أَهْلَ الْفَضْلِ، وَيَمْزَحُ وَلَا يَقُوْلُ إِلَّا حَقًّا يُحِبُّهُ اللهُ تَعَالَى وَيَرْضَاهْ", "lt": "Wa yata'allafu ahlasy-syarafi wa yukrimu ahlal-fadll, wa yamzaḥu wa lâ yaqûlu illâ ḥaqqan yuḥibbuhullâhu ta‘âlâ wa yardlâh", "id": "Beliau melunakkan hati orang-orang terhormat dan memuliakan orang-orang yang memiliki keutamaan. Beliau bercanda, namun tidak berkata kecuali yang benar, yang dicintai dan diridai Allah Ta‘ala.", "no": 8},
{"ar": "وَهٰهُنَا وَقَفَ بِنَا جَوَادُ الْمَقَالِ عَنِ الطِّرَادِ فِي الْحَلْبَةِ الْبَيَانِيَّةْ، وَبَلَغَ ظَاعِنُ الْإِمْلَاءِ فِيْ فَدَافِدِ الْإِيْضَاحِ مُنْتَهَاهْ", "lt": "Wa hâhunâ waqafa binâ jawâdul-maqâli ‘aniṭ-ṭirâdi fil-ḥalbatil-bayâniyyah, wa balagha dhâ‘inul-imlâ'i fî fadâfidil-îdlâḥi muntahâh", "id": "Sampai di sini kuda ucapan kami berhenti berlari di arena penjelasan, dan pengembara tulisan ini telah sampai di ujung padang penjelasannya.", "no": 9},
{"ar": "عَطِّرِ اللّٰهُمَّ قَبْرَهُ الْكَرِيْمْ ۞ بِعَرْفٍ شَذِيٍّ مِنْ صَلَاةٍ وَتَسْلِيْمْ", "lt": "‘Aṭṭiril-lâhumma qabrahul-karîm ۞ bi‘arfin syadziyyin min shalâtin wa taslîm", "id": "Ya Allah, harumkanlah kubur beliau yang mulia dengan semerbak wangi shalawat dan salam.", "no": 10}]},
{judul:"Doa Maulid Barzanji",isi:[
{"ar": "اَللّٰهُمَّ يَا بَاسِطَ الْيَدَيْنِ بِالْعَطِيَّةْ، يَا مَنْ إِذَا رُفِعَتْ إِلَيْهِ أَكُفُّ الْعَبْدِ كَفَاهْ", "lt": "Allâhumma yâ bâsiṭal-yadaini bil-‘aṭiyyah, yâ man idzâ rufi‘at ilaihi akuffu-l-‘abdi kafâh", "id": "Ya Allah, wahai Yang membentangkan kedua tangan-Nya dengan pemberian, wahai Yang bila telapak tangan hamba diangkat kepada-Nya, Dia mencukupinya.", "no": 1},
{"ar": "يَا مَنْ تَنَزَّهَ فِيْ ذَاتِهِ وَصِفَاتِهِ الْأَحَدِيَّةْ، عَنْ أَنْ يَكُوْنَ لَهُ فِيْهَا نَظَائِرُ وَأَشْبَاهْ", "lt": "Yâ man tanazzaha fî dzâtihî wa shifâtihil-aḥadiyyah, ‘an an yakûna lahû fîhâ nadhâ'iru wa asybâh", "id": "Wahai Yang Mahasuci dalam Dzat dan sifat-sifat-Nya yang Esa dari memiliki tandingan dan keserupaan.", "no": 2},
{"ar": "يَا مَنْ تَفَرَّدَ بِالْبَقَاءِ وَالْقِدَمِ وَالْأَزَلِيَّةْ، يَا مَنْ لَا يُرْجَى غَيْرُهُ وَلَا يُعَوَّلُ عَلَى سِوَاهْ", "lt": "Yâ man tafarrada bil-baqâ'i wal-qidami wal-azaliyyah, yâ man lâ yurjâ ghairuhû wa lâ yu‘awwalu ‘alâ siwâh", "id": "Wahai Yang Maha Esa dalam kekekalan, keterdahuluan, dan keazalian; wahai Yang tidak diharapkan selain Dia dan tidak diandalkan selain-Nya.", "no": 3},
{"ar": "يَا مَنِ اسْتَنَدَ الْأَنَامُ إِلَى قُدْرَتِهِ الْقَيُّوْمِيَّةْ، وَأَرْشَدَ بِفَضْلِهِ مَنِ اسْتَرْشَدَهُ وَاسْتَهْدَاهْ", "lt": "Yâ manistanadal-anâmu ilâ qudratihil-qayyûmiyyah, wa arsyada bifadllihî manistarsyadahû wastahdâh", "id": "Wahai Yang kepada kekuasaan-Nya yang Maha Berdiri Sendiri seluruh makhluk bersandar, dan Yang dengan karunia-Nya memberi bimbingan kepada orang yang memohon bimbingan dan petunjuk-Nya.", "no": 4},
{"ar": "نَسْأَلُكَ بِأَنْوَارِكَ الْقُدْسِيَّةْ، الَّتِيْ أَزَاحَتْ مِنْ ظُلُمَاتِ الشَّكِّ دُجَاهْ", "lt": "Nas'aluka bi'anwârikal-qudsiyyah, al-latî azâḥat min dhulumâtisy-syakki dujâh", "id": "Kami memohon kepada-Mu dengan cahaya-cahaya-Mu yang suci, yang telah menyingkap kegelapan keraguan.", "no": 5},
{"ar": "وَنَتَوَسَّلُ إِلَيْكَ بِشَرَفِ الذَّاتِ الْمُحَمَّدِيَّةْ، وَمَنْ هُوَ آخِرُ الْأَنْبِيَاءِ بِصُوْرَتِهِ وَأَوَّلُهُمْ بِمَعْنَاهْ", "lt": "Wa natawassalu ilaika bisyarafidz-dzâtil-muḥammadiyyah, wa man huwa âkhirul-anbiyâ'i bishûratihî wa awwaluhum bima‘nâh", "id": "Kami bertawasul kepada-Mu dengan kemuliaan pribadi Muhammad, yang dalam rupanya adalah nabi terakhir, namun dalam maknanya adalah yang pertama di antara mereka.", "no": 6},
{"ar": "وَبِآلِهِ كَوَاكِبِ أَمْنِ الْبَرِيَّةْ، وَسَفِيْنَةِ السَّلَامَةِ وَالنَّجَاهْ", "lt": "Wa bi'âlihî kawâkibi amnil-bariyyah, wa safînatis-salâmati wan-najâh", "id": "Dan dengan keluarganya, bintang-bintang pengaman bagi makhluk, dan bahtera keselamatan serta kelepasan (dari bahaya).", "no": 7},
{"ar": "وَبِأَصْحَابِهِ أُوْلِي الْهِدَايَةِ وَالْأَفْضَلِيَّةْ، الَّذِيْنَ بَذَلُوْا نُفُوْسَهُمْ لِلّٰهِ يَبْتَغُوْنَ فَضْلًا مِنَ اللهْ", "lt": "Wa bi'ash-ḥâbihî ulil-hidâyati wal-afdlaliyyah, al-ladzîna badzalû nufûsahum lillâhi yabtaghûna fadllan minallâh", "id": "Dan dengan para sahabatnya yang memiliki petunjuk dan keutamaan, yang telah mengorbankan jiwa mereka untuk Allah demi mengharap karunia dari Allah.", "no": 8},
{"ar": "وَبِحَمَلَةِ شَرِيْعَتِهِ أُوْلِي الْمَنَاقِبِ وَالْخُصُوْصِيَّةْ، الَّذِيْنَ اسْتَبْشَرُوْا بِنِعْمَةٍ وَفَضْلٍ مِنَ اللهْ", "lt": "Wa biḥamalati syarî‘atihî ulil-manâqibi wal-khushûshiyyah, al-ladzînas-tabsyarû bini‘matin wa fadllin minallâh", "id": "Dan dengan para pengemban syariatnya yang memiliki keutamaan dan keistimewaan, yang bergembira dengan nikmat dan karunia dari Allah.", "no": 9},
{"ar": "أَنْ تُوَفِّقَنَا فِي الْأَقْوَالِ وَالْأَعْمَالِ لِإِخْلَاصِ النِّيَّةْ، وَتُنْجِحَ لِكُلٍّ مِنَ الْحَاضِرِيْنَ مَطْلَبَهُ وَمُنَاهْ", "lt": "An tuwaffiqanâ fil-aqwâli wal-a‘mâli li'ikhlâshin-niyyah, wa tunjiḥa likullin minal-ḥâdlirîna maṭlabahû wa munâh", "id": "Agar Engkau memberi kami taufik untuk ikhlas dalam niat pada setiap ucapan dan perbuatan, dan Engkau sukseskan bagi setiap orang yang hadir apa yang ia cari dan cita-citakan.", "no": 10},
{"ar": "وَتُخَلِّصَنَا مِنْ أَسْرِ الشَّهَوَاتِ وَالْأَدْوَاءِ الْقَلْبِيَّةْ، وَتُحَقِّقَ لَنَا مِنَ الْآمَالِ مَا بِكَ ظَنَنَّاهْ", "lt": "Wa tukhallishanâ min asrisy-syahawâti wal-adwâ'il-qalbiyyah, wa tuḥaqqiqa lanâ minal-âmâli mâ bika dhanannâh", "id": "Selamatkanlah kami dari belenggu syahwat dan penyakit-penyakit hati, dan wujudkanlah bagi kami harapan-harapan yang kami sangkakan (dengan baik) kepada-Mu.", "no": 11},
{"ar": "وَتَكْفِيَنَا كُلَّ مُدْلَهِمَّةٍ وَبَلِيَّةْ، وَلَا تَجْعَلَنَا مِمَّنْ أَهْوَاهُ هَوَاهْ", "lt": "Wa takfiyanâ kulla mudlahimmatin wa baliyyah, wa lâ taj‘alanâ mimman ahwâhu hawâh", "id": "Cukupkanlah kami dari setiap kegelapan dan bencana, dan janganlah Engkau jadikan kami termasuk orang yang dijatuhkan oleh hawa nafsunya.", "no": 12},
{"ar": "وَتُدْنِيَ لَنَا مِنْ حُسْنِ الْيَقِيْنِ قُطُوْفًا دَانِيَةً جَنِيَّةْ، وَتَمْحُوَ عَنَّا كُلَّ ذَنْبٍ جَنَيْنَاهْ", "lt": "Wa tudniya lanâ min ḥusnil-yaqîni quṭûfan dâniyatan janiyyah, wa tamḥuwa ‘annâ kulla dzanbin janainâh", "id": "Dekatkanlah kepada kami buah-buah keyakinan yang baik, yang dekat lagi siap dipetik, dan hapuskanlah dari kami setiap dosa yang telah kami lakukan.", "no": 13},
{"ar": "وَتَسْتُرَ لِكُلٍّ مِنَّا عَيْبَهُ وَعَجْزَهُ وَحَصْرَهُ وَعِيَّهْ، وَتُسَهِّلَ لَنَا مِنْ صَالِحِ الْأَعْمَالِ مَا عَزَّ ذُرَاهْ", "lt": "Wa tastura likullin minnâ ‘aibahû wa ‘ajzahû wa ḥashrahû wa ‘iyyah, wa tusahhila lanâ min shâliḥil-a‘mâli mâ ‘azza dzurâh", "id": "Tutupilah aib, kelemahan, kegagapan, dan ketidakmampuan (berbicara) setiap orang di antara kami, dan mudahkanlah bagi kami amal-amal saleh yang sulit dicapai puncaknya.", "no": 14},
{"ar": "وَتَعُمَّ جَمْعَنَا هٰذَا مِنْ خَزَائِنِ مِنَحِكَ السَّنِيَّةْ، بِرَحْمَةٍ وَمَغْفِرَةٍ وَتُدِيْمَ عَمَّنْ سِوَاكَ غِنَاهْ", "lt": "Wa ta‘umma jam‘anâ hâdzâ min khazâ'ini minaḥikas-saniyyah, biraḥmatin wa maghfiratin wa tudîma ‘amman siwâka ghinâh", "id": "Liputilah perkumpulan kami ini, dari perbendaharaan anugerah-Mu yang luhur, dengan rahmat dan ampunan, dan langgengkanlah kecukupan (kami) dari selain-Mu.", "no": 15},
{"ar": "اَللّٰهُمَّ إِنَّكَ جَعَلْتَ لِكُلِّ سَائِلٍ مَقَامًا وَمَزِيَّةْ، وَلِكُلِّ رَاجٍ مَا أَمَّلَهُ فِيْكَ وَرَجَاهْ", "lt": "Allâhumma innaka ja‘alta likulli sâ'ilin maqâman wa maziyyah, wa likulli râjin mâ ammalahû fîka wa rajâh", "id": "Ya Allah, sesungguhnya Engkau telah menjadikan bagi setiap peminta kedudukan dan keistimewaan, dan bagi setiap orang yang berharap apa yang ia angankan dan harapkan dari-Mu.", "no": 16},
{"ar": "وَقَدْ سَأَلْنَاكَ رَاجِيْنَ مَوَاهِبَكَ اللَّدُنِّيَّةْ، فَحَقِّقْ لَنَا مَا مِنْكَ رَجَوْنَاهْ", "lt": "Wa qad sa'alnâka râjîna mawâhibakal-ladunniyyah, faḥaqqiq lanâ mâ minka rajaunâh", "id": "Kami telah memohon kepada-Mu seraya mengharapkan anugerah-anugerah dari sisi-Mu, maka wujudkanlah bagi kami apa yang kami harapkan dari-Mu.", "no": 17},
{"ar": "اَللّٰهُمَّ آمِنِ الرَّوْعَاتِ، وَأَصْلِحِ الرُّعَاةَ وَالرَّعِيَّةْ، وَأَعْظِمِ الْأَجْرَ لِمَنْ جَعَلَ هٰذَا الْخَيْرَ فِيْ هٰذَا الْيَوْمِ وَأَجْرَاهْ", "lt": "Allâhumma âminir-rau‘ât, wa ashliḥir-ru‘âta war-ra‘iyyah, wa a‘dhimil-ajra liman ja‘ala hâdzal-khaira fî hâdzal-yaumi wa ajrâh", "id": "Ya Allah, amankanlah segala ketakutan, perbaikilah para pemimpin dan rakyat, dan besarkanlah pahala bagi orang yang menyelenggarakan dan melangsungkan kebaikan ini pada hari ini.", "no": 18},
{"ar": "اَللّٰهُمَّ اجْعَلْ هٰذِهِ الْبَلْدَةَ وَسَائِرَ بِلَادِ الْإِسْلَامِ آمِنَةً رَخِيَّةْ، وَاسْقِنَا غَيْثًا يَعُمُّ انْسِيَابُ سَيْبِهِ السَّبْسَبَ وَرُبَاهْ", "lt": "Allâhummaj-‘al hâdzihil-baldata wa sâ'ira bilâdil-islâmi âminatan rakhiyyah, wasqinâ ghaitsan ya‘ummun-siyâbu saibihis-sabsaba wa rubâh", "id": "Ya Allah, jadikanlah negeri ini dan seluruh negeri Islam aman dan makmur, dan turunkanlah kepada kami hujan yang alirannya merata ke padang-padang dan bukit-bukitnya.", "no": 19},
{"ar": "وَاغْفِرْ لِنَاسِخِ هٰذِهِ الْبُرُوْدِ الْمُحَبَّرَةِ الْمَوْلِدِيَّةْ، سَيِّدِنَا جَعْفَرٍ مَنْ إِلَى الْبَرْزَنْجِيِّ نِسْبَتُهُ وَمُنْتَمَاهْ", "lt": "Waghfir linâsikhi hâdzihil-burûdil-muḥabbaratil-maulidiyyah, sayyidinâ ja‘farin man ilal-barzanjiyyi nisbatuhû wa muntamâh", "id": "Ampunilah penyusun kain-kain (kisah) maulid yang terhias indah ini, Sayyid Ja‘far, yang nasab dan nisbatnya kepada Barzanji.", "no": 20},
{"ar": "وَحَقِّقْ لَهُ الْفَوْزَ بِقُرْبِكَ وَالرَّجَاءَ وَالْأُمْنِيَّةْ، وَاجْعَلْ مَعَ الْمُقَرَّبِيْنَ مَقِيْلَهُ وَسُكْنَاهْ", "lt": "Wa ḥaqqiq lahul-fauza biqurbika war-rajâ'a wal-umniyyah, waj‘al ma‘al-muqarrabîna maqîlahû wa suknâh", "id": "Wujudkanlah baginya keberuntungan dengan dekat kepada-Mu, juga harapan dan cita-citanya, dan jadikanlah tempat istirahat dan tinggalnya bersama orang-orang yang didekatkan (kepada-Mu).", "no": 21},
{"ar": "وَاسْتُرْ لَهُ عَيْبَهُ وَعَجْزَهُ وَحَصْرَهُ وَعِيَّهْ، وَكَاتِبِهَا وَقَارِئِهَا وَمَنْ أَصَاخَ إِلَيْهَا سَمْعَهُ وَأَصْغَاهْ", "lt": "Wastur lahû ‘aibahû wa ‘ajzahû wa ḥashrahû wa ‘iyyah, wa kâtibihâ wa qâri'ihâ wa man ashâkha ilaihâ sam‘ahû wa ashghâh", "id": "Tutupilah aib, kelemahan, kegagapan, dan ketidakmampuannya, juga (aib) penulisnya, pembacanya, dan orang yang memasang telinga untuk mendengarkannya.", "no": 22},
{"ar": "اَللّٰهُمَّ وَصَلِّ وَسَلِّمْ عَلَى أَوَّلِ قَابِلٍ لِلتَّجَلِّيْ مِنَ الْحَقِيْقَةِ الْكُلِّيَّةْ، وَعَلَى آلِهِ وَصَحْبِهِ وَمَنْ نَصَرَهُ وَوَالَاهْ", "lt": "Allâhumma wa shalli wa sallim ‘alâ awwali qâbilin lit-tajallî minal-ḥaqîqatil-kulliyyah, wa ‘alâ âlihî wa shaḥbihî wa man nasharahû wa wâlâh", "id": "Ya Allah, limpahkanlah shalawat dan salam kepada (Nabi) yang pertama menerima penampakan dari hakikat yang menyeluruh, juga kepada keluarga, para sahabatnya, serta orang-orang yang menolong dan membelanya,", "no": 23},
{"ar": "مَا شُنِّفَتِ الْآذَانُ مِنْ وَصْفِهِ الدُّرِّيِّ بِأَقْرَاطٍ جَوْهَرِيَّةْ، وَتَحَلَّتْ صُدُوْرُ الْمَحَافِلِ الْمُنِيْفَةِ بِعُقُوْدِ حُلَاهْ", "lt": "Mâ syunnifatil-âdzânu min washfihid-durriyyi bi'aqrâṭin jauhariyyah, wa taḥallat shudûrul-maḥâfilil-munîfati bi‘uqûdi ḥulâh", "id": "selama telinga-telinga dihiasi anting-anting permata dari sifat-sifatnya yang bagaikan mutiara, dan selama dada majelis-majelis yang mulia berhias kalung-kalung keindahannya.", "no": 24},
{"ar": "وَأَفْضَلُ الصَّلَاةِ وَأَتَمُّ التَّسْلِيْمِ عَلَى سَيِّدِنَا وَمَوْلَانَا خَاتَمِ الْأَنْبِيَاءِ وَالْمُرْسَلِيْنَ، وَعَلَى آلِهِ وَصَحْبِهِ أَجْمَعِيْنَ", "lt": "Wa afdlalush-shalâti wa atammut-taslîmi ‘alâ sayyidinâ wa maulânâ khâtamil-anbiyâ'i wal-mursalîn, wa ‘alâ âlihî wa shaḥbihî ajma‘în", "id": "Shalawat yang paling utama dan salam yang paling sempurna semoga tercurah kepada junjungan dan pemimpin kami, penutup para nabi dan rasul, serta kepada keluarga dan seluruh sahabatnya.", "no": 25},
{"ar": "سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُوْنَ، وَسَلَامٌ عَلَى الْمُرْسَلِيْنَ، وَالْحَمْدُ لِلّٰهِ رَبِّ الْعَالَمِيْنَ", "lt": "Subḥâna rabbika rabbil-‘izzati ‘ammâ yashifûn, wa salâmun ‘alal-mursalîn, wal-ḥamdu lillâhi rabbil-‘âlamîn", "id": "Maha Suci Tuhanmu, Tuhan Yang Mahaperkasa, dari apa yang mereka sifatkan. Salam sejahtera bagi para rasul, dan segala puji bagi Allah, Tuhan semesta alam.", "no": 26}]}]});
